window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-f5ce8c3b9c723c57"]={"versions": [{"id": "FIG-f5ce8c3b9c723c57", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Diagrammtyp:</strong> AUTOSAR M2-Metamodell-Ausschnitt als UML-Klassendiagramm (Strukturdiagramm).\n</li><li><strong>Architektur-Kontext:</strong> Definition der Wurzelebene des BSW Module Description Templates (BSWMDT, AUTOSAR Classic Platform R4.0.3).\n</li><li><strong>Funktionaler Zweck:</strong> Formale Spezifikation der äußeren Hülle eines Basissoftware-Moduls (<code>BswModuleDescription</code>). Dient als maschinenlesbarer Vertrag (ARXML) für den BSW- und RTE/SchM-Generator zur Definition von Funktionsschnittstellen (APIs/Callbacks), Modulabhängigkeiten, Mode- und Trigger-Interaktionen sowie als Anker für das interne Verhalten (<code>BswInternalBehavior</code>).\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Entitäten und Klassenhierarchie</h5>\n<ul class=\"fig-list\"><li><strong><code>BswModuleDescription</code></strong>\n<ul class=\"fig-list\"><li><em>Vererbung / Stereotypen:</em> <code>ARElement</code>, <code>AtpBlueprint</code>, <code>AtpBlueprintable</code>, <code>AtpStructureElement</code>.\n</li><li><em>Attribute:</em> <code>+ moduleId: PositiveInteger</code> (Normierte AUTOSAR-BSW-Modul-ID, z. B. Can=80, Com=50; normativ validiert über <code>[constr_4019]</code>).\n</li><li><em>Rolle:</em> Top-Level-Beschreibungscontainer für ein einzelnes BSW-Modul (Treiber, Stack, Service).\n</li></ul>\n</li><li><strong><code>BswModuleEntry</code></strong>\n<ul class=\"fig-list\"><li><em>Vererbung / Stereotypen:</em> <code>ARElement</code>, <code>AtpBlueprint</code>, <code>AtpBlueprintable</code>.\n</li><li><em>Rolle:</em> Repräsentiert die C-Funktionssignatur (C-API-Funktion, Main-Function oder Callback) auf C-Quellcodeebene.\n</li></ul>\n</li><li><strong><code>BswModuleDependency</code></strong>\n<ul class=\"fig-list\"><li><em>Vererbung / Stereotypen:</em> <code>Identifiable</code>.\n</li><li><em>Attribute:</em> <code>+ targetModuleId: PositiveInteger</code> (Modul-ID des Zielmoduls).\n</li><li><em>Rolle:</em> Kapselt die vertraglichen Schnittstellenanforderungen an ein anderes BSW-Modul.\n</li></ul>\n</li><li><strong><code>ModeDeclarationGroupPrototype</code> &amp; <code>ModeDeclarationGroup</code></strong>\n<ul class=\"fig-list\"><li><em><code>ModeDeclarationGroupPrototype</code>:</em> Stereotyp <code>AtpPrototype</code>, Attribut <code>+ swCalibrationAccess: SwCalibrationAccessEnum [0..1]</code>.\n</li><li><em><code>ModeDeclarationGroup</code>:</em> Stereotypen <code>ARElement</code>, <code>AtpBlueprint</code>, <code>AtpBlueprintable</code>, <code>AtpType</code>, Attribut <code>+ onTransitionValue: PositiveInteger [0..1]</code>.\n</li><li><em>Typisierung:</em> Type-Prototype-Pattern über <code>«isOfType»</code> (<code>+type: ModeDeclarationGroup [1]</code> redefiniert <code>atpType</code>).\n</li><li><em>Rolle:</em> Deklaration von BSW-Zustandsmodi (z. B. Kommunikationsmodi im <code>ComM</code>, ECU-Zustände im <code>EcuM</code>).\n</li></ul>\n</li><li><strong><code>Trigger</code></strong>\n<ul class=\"fig-list\"><li><em>Vererbung / Stereotypen:</em> <code>AtpStructureElement</code>, <code>Identifiable</code>.\n</li><li><em>Attribute:</em> <code>+ swImplPolicy: SwImplPolicyEnum [0..1]</code>.\n</li><li><em>Rolle:</em> Ereignisquelle für asynchrone Prozessaktivierungen ohne Parameterübertragung.\n</li></ul>\n</li><li><strong><code>BswInternalBehavior</code></strong>\n<ul class=\"fig-list\"><li><em>Vererbung / Stereotypen:</em> <code>InternalBehavior</code>.\n</li><li><em>Rolle:</em> Kapselung von BSW-Schedulable-Entities, Exclusive Areas, BSW-Events und Task-Mappings.\n</li></ul>\n</li><li><strong><code>SwComponentDocumentation</code></strong>\n<ul class=\"fig-list\"><li><em>Archetyp:</em> Tag <code>A</code>.\n</li><li><em>Rolle:</em> Strukturierte technische Dokumentation des Moduls.\n</li></ul>\n</li></ul>\n<h5 class=\"fig-section-h5\">Beziehungen, Kardinalitäten und Stereotypen</h5>\n<div class=\"table-wrap\"><table class=\"fig-table\"><thead><tr><th>Quell-Element</th><th>Relation / Rolle</th><th>Ziel-Element</th><th>Kardinalität</th><th>Stereotypen</th><th>Semantik</th></tr></thead><tbody><tr><td><code>BswModuleDescription</code></td><td>Komposition <code>+bswModuleDocumentation</code></td><td><code>SwComponentDocumentation</code></td><td><code>0..1</code></td><td><code>«atpVariation, atpSplitable»</code></td><td>Dokumentationsanhang; varianten- und dateisplitfähig</td></tr><tr><td><code>BswModuleDescription</code></td><td>Assoziation <code>+providedEntry</code></td><td><code>BswModuleEntry</code></td><td><code>0..*</code></td><td><code>«atpVariation»</code></td><td>Vom Modul implementierte und exportierte C-APIs</td></tr><tr><td><code>BswModuleDescription</code></td><td>Assoziation <code>+outgoingCallback</code></td><td><code>BswModuleEntry</code></td><td><code>0..*</code></td><td><code>«atpVariation»</code></td><td>Vom Modul aktiv aufgerufene Callbacks nach außen</td></tr><tr><td><code>BswModuleDescription</code></td><td>Komposition <code>+bswModuleDependency</code></td><td><code>BswModuleDependency</code></td><td><code>0..*</code></td><td><code>«atpVariation, atpSplitable»</code></td><td>Deklarierte Abhängigkeit zu anderen BSW-Modulen</td></tr><tr><td><code>BswModuleDependency</code></td><td>Assoziation <code>+requiredEntry</code></td><td><code>BswModuleEntry</code></td><td><code>0..*</code></td><td><code>«atpVariation»</code></td><td>Benötigte C-APIs des Zielmoduls</td></tr><tr><td><code>BswModuleDependency</code></td><td>Assoziation <code>+expectedCallback</code></td><td><code>BswModuleEntry</code></td><td><code>0..*</code></td><td><code>«atpVariation»</code></td><td>Vom Zielmodul erwartete Callback-Implementierungen</td></tr><tr><td><code>BswModuleDescription</code></td><td>Komposition <code>+providedModeGroup</code></td><td><code>ModeDeclarationGroupPrototype</code></td><td><code>0..*</code></td><td><code>«atpVariation»</code></td><td>Vom Modul verwaltete / bereitgestellte Zustandsmodi</td></tr><tr><td><code>BswModuleDescription</code></td><td>Komposition <code>+requiredModeGroup</code></td><td><code>ModeDeclarationGroupPrototype</code></td><td><code>0..*</code></td><td><code>«atpVariation»</code></td><td>Vom Modul überwachte / benötigte Zustandsmodi</td></tr><tr><td><code>BswModuleDescription</code></td><td>Komposition <code>+releasedTrigger</code></td><td><code>Trigger</code></td><td><code>0..*</code></td><td><code>«atpVariation»</code></td><td>Geworfene Trigger für RTE/BswM</td></tr><tr><td><code>BswModuleDescription</code></td><td>Komposition <code>+requiredTrigger</code></td><td><code>Trigger</code></td><td><code>0..*</code></td><td><code>«atpVariation»</code></td><td>Konsumierte Trigger zur Aktivierung von Entities</td></tr><tr><td><code>BswModuleDescription</code></td><td>Komposition <code>+internalBehavior</code></td><td><code>BswInternalBehavior</code></td><td><code>0..*</code></td><td><code>«atpSplitable»</code></td><td>Internes Ausführungsverhalten (Split erlaubt Trennung über ARXML-Dateien)</td></tr></tbody></table></div>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Schnittstellen-Semantik</h4>\n<p class=\"fig-p\">Obgleich ein statisches Metamodell vorliegt, erzwingt die Struktur folgende dynamische Interaktionsmuster zur Laufzeit:</p>\n<ul class=\"fig-list\"><li><strong>Synchroner Aufrufpfad (Direct C-Call / Inter-Module-API):</strong>\n<ul class=\"fig-list\"><li><code>providedEntry</code> definiert Einstiegspunkte für synchrone Aufrufe (z. B. <code>CanIf_Transmit</code> aufgerufen durch <code>PduR</code>).\n</li><li><code>requiredEntry</code> in <code>BswModuleDependency</code> verknüpft diesen Aufruf statisch mit der Modul-ID des Zielmoduls (<code>targetModuleId</code>), validiert während der Link-Time-/Generierungsphase.\n</li></ul>\n</li><li><strong>Callback-Fluss:</strong>\n<ul class=\"fig-list\"><li><code>outgoingCallback</code> definiert Auslösepunkte (z. B. Interrupt-Kontext oder ISR-Deferred-Verarbeitung).\n</li><li><code>expectedCallback</code> stellt sicher, dass das aufrufende Modul eine kompatible Signatur des Ziels vorfindet (z. B. <code>CanIf_RxIndication</code> erwartet durch den CAN-Treiber).\n</li></ul>\n</li><li><strong>Mode-Switching &amp; State-Propagation:</strong>\n<ul class=\"fig-list\"><li>Statusänderungen über <code>providedModeGroup</code> triggeren Moduswechsel im BSW Mode Manager (<code>BswM</code>) oder in abhängigen Modulen (<code>requiredModeGroup</code>).\n</li></ul>\n</li><li><strong>Asynchrones Triggering:</strong>\n<ul class=\"fig-list\"><li>Ein <code>releasedTrigger</code> kann über den SchM/OS-Dispatcher ohne PDU-Payload eine Taskaktivierung oder die Ausführung verknüpfter BswSchedulableEntities auslösen (<code>requiredTrigger</code>).\n</li></ul>\n</li></ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>BSWMD-Erstellung (Treiber- &amp; Stack-Lieferanten):</strong>\n<ul class=\"fig-list\"><li>Jedes BSW-Modul muss eine konforme ARXML-Datei liefern, deren Wurzel <code>BswModuleDescription</code> ist.\n</li><li><code>moduleId</code> muss zwingend mit der in den AUTOSAR-Spezifikationen definierten BSW-Modul-Nummer übereinstimmen (<code>[constr_4019]</code>), da Generatoren wie Det, Dem oder SchM hierüber Modul-Instanzen eindeutig auflösen.\n</li></ul>\n</li><li><strong>Generierung des Basic Software Schedulers (SchM):</strong>\n<ul class=\"fig-list\"><li>Die Verknüpfung von <code>BswModuleDescription</code> mit <code>BswInternalBehavior</code> steuert die Generierung der <code>SchM_&lt;Bsw&gt;.h</code>-Header (z. B. Exclusive Areas via <code>SchM_Enter_&lt;Mod&gt;_&lt;Area&gt;()</code> und zyklische Main-Functions via <code>SchM_ActMainFunction_&lt;Mod&gt;()</code>).\n</li></ul>\n</li><li><strong>Metamodell-Regeln für das Packaging:</strong>\n<ul class=\"fig-list\"><li>Durch <code>«atpSplitable»</code> an <code>internalBehavior</code>, <code>bswModuleDocumentation</code> und <code>bswModuleDependency</code> dürfen Modulbeschreibung und internes Verhalten in getrennten ARXML-Dateien ausgeliefert werden (z. B. Schnittstellenbeschreibung als OEM-Vorgabe, <code>BswInternalBehavior</code> durch den Tier-1/Stack-Zulieferer).\n</li><li><code>«atpVariation»</code> erlaubt Post-Build- oder Pre-Compile-Variantenbildung auf Ebene von Callbacks, Entries, Triggern und Moden über System-Constants (<code>SwcImplementations</code>/VFB-Varianz).\n</li></ul>\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-0426f7d89d8bb8d2", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Diagrammtyp:</strong> AUTOSAR M2-Metamodell-Ausschnitt als UML-Klassendiagramm (Strukturdiagramm).\n</li><li><strong>Architektur-Kontext:</strong> Definition der Wurzelebene des BSW Module Description Templates (BSWMDT, AUTOSAR Classic Platform R4.0.3).\n</li><li><strong>Funktionaler Zweck:</strong> Formale Spezifikation der äußeren Hülle eines Basissoftware-Moduls (<code>BswModuleDescription</code>). Dient als maschinenlesbarer Vertrag (ARXML) für den BSW- und RTE/SchM-Generator zur Definition von Funktionsschnittstellen (APIs/Callbacks), Modulabhängigkeiten, Mode- und Trigger-Interaktionen sowie als Anker für das interne Verhalten (<code>BswInternalBehavior</code>).\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Entitäten und Klassenhierarchie</h5>\n<ul class=\"fig-list\"><li><strong><code>BswModuleDescription</code></strong>\n<ul class=\"fig-list\"><li><em>Vererbung / Stereotypen:</em> <code>ARElement</code>, <code>AtpBlueprint</code>, <code>AtpBlueprintable</code>, <code>AtpStructureElement</code>.\n</li><li><em>Attribute:</em> <code>+ moduleId: PositiveInteger [0..1]</code> (Normierte AUTOSAR-BSW-Modul-ID).\n</li><li><em>Rolle:</em> Top-Level-Beschreibungscontainer für ein einzelnes BSW-Modul (Treiber, Stack, Service).\n</li></ul>\n</li><li><strong><code>BswModuleEntry</code></strong>\n<ul class=\"fig-list\"><li><em>Vererbung / Stereotypen:</em> <code>ARElement</code>, <code>AtpBlueprint</code>, <code>AtpBlueprintable</code>.\n</li><li><em>Rolle:</em> Repräsentiert eine C-Funktionssignatur (C-API-Funktion, Main-Function oder Callback) auf C-Quellcodeebene.\n</li></ul>\n</li><li><strong><code>BswModuleDependency</code></strong>\n<ul class=\"fig-list\"><li><em>Vererbung / Stereotypen:</em> <code>Identifiable</code>.\n</li><li><em>Attribute:</em> <code>+ targetModuleId: PositiveInteger [0..1]</code> (Modul-ID des Zielmoduls).\n</li><li><em>Rolle:</em> Kapselt die vertraglichen Schnittstellenanforderungen an ein anderes BSW-Modul.\n</li></ul>\n</li><li><strong><code>ModeDeclarationGroupPrototype</code></strong>\n<ul class=\"fig-list\"><li><em>Vererbung / Stereotypen:</em> <code>AtpPrototype</code>.\n</li><li><em>Attribute:</em> <code>+ swCalibrationAccess: SwCalibrationAccessEnum [0..1]</code>.\n</li><li><em>Rolle:</em> Prototyp einer Modus-Deklarationsgruppe zur Festlegung von BSW-Zustandsmodi.\n</li></ul>\n</li><li><strong><code>Trigger</code></strong>\n<ul class=\"fig-list\"><li><em>Vererbung / Stereotypen:</em> <code>AtpStructureElement</code>, <code>Identifiable</code>.\n</li><li><em>Attribute:</em> <code>+ swImplPolicy: SwImplPolicyEnum [0..1]</code>.\n</li><li><em>Rolle:</em> Ereignisquelle für asynchrone Prozessaktivierungen ohne Parameterübertragung.\n</li></ul>\n</li><li><strong><code>BswModuleClientServerEntry</code></strong>\n<ul class=\"fig-list\"><li><em>Vererbung / Stereotypen:</em> <code>Referrable</code>.\n</li><li><em>Attribute:</em> <code>+ isReentrant: Boolean [0..1]</code>, <code>+ isSynchronous: Boolean [0..1]</code>.\n</li><li><em>Rolle:</em> Kapselt eine Client-Server-Schnittstelle innerhalb des BSW inklusive Synchronitäts- und Reentrancy-Eigenschaften.\n</li></ul>\n</li><li><strong><code>VariableDataPrototype</code></strong>\n<ul class=\"fig-list\"><li><em>Vererbung / Stereotypen:</em> <code>AutosarDataPrototype</code>.\n</li><li><em>Rolle:</em> Repräsentiert typisierte Datenprototypen für datenbasierte Schnittstellen (Sender-Receiver bzw. Data Exchange).\n</li></ul>\n</li><li><strong><code>BswInternalBehavior</code></strong>\n<ul class=\"fig-list\"><li><em>Vererbung / Stereotypen:</em> <code>InternalBehavior</code>.\n</li><li><em>Rolle:</em> Kapselung von BSW-Schedulable-Entities, Exclusive Areas, BSW-Events und Task-Mappings.\n</li></ul>\n</li><li><strong><code>SwComponentDocumentation</code></strong>\n<ul class=\"fig-list\"><li><em>Archetyp:</em> Tag <code>A</code>.\n</li><li><em>Rolle:</em> Strukturierte technische Dokumentation des Moduls.\n</li></ul>\n</li></ul>\n<h5 class=\"fig-section-h5\">Beziehungen, Kardinalitäten und Stereotypen</h5>\n<div class=\"table-wrap\"><table class=\"fig-table\"><thead><tr><th>Quell-Element</th><th>Relation / Rolle</th><th>Ziel-Element</th><th>Kardinalität</th><th>Stereotypen</th><th>Semantik</th></tr></thead><tbody><tr><td><code>BswModuleDescription</code></td><td>Komposition <code>+bswModuleDocumentation</code></td><td><code>SwComponentDocumentation</code></td><td><code>0..1</code></td><td><code>«atpVariation, atpSplitable»</code></td><td>Dokumentationsanhang; varianten- und dateisplitfähig</td></tr><tr><td><code>BswModuleDescription</code></td><td>Assoziation <code>+providedEntry</code></td><td><code>BswModuleEntry</code></td><td><code>0..*</code></td><td><code>«atpVariation»</code></td><td>Vom Modul implementierte und exportierte C-APIs</td></tr><tr><td><code>BswModuleDescription</code></td><td>Assoziation <code>+outgoingCallback</code></td><td><code>BswModuleEntry</code></td><td><code>0..*</code></td><td><code>«atpVariation»</code></td><td>Vom Modul aktiv aufgerufene Callbacks nach außen</td></tr><tr><td><code>BswModuleDescription</code></td><td>Komposition <code>+bswModuleDependency</code></td><td><code>BswModuleDependency</code></td><td><code>0..*</code></td><td><code>«atpVariation, atpSplitable»</code></td><td>Deklarierte Abhängigkeit zu anderen BSW-Modulen</td></tr><tr><td><code>BswModuleDependency</code></td><td>Assoziation <code>+targetModuleRef</code></td><td><code>BswModuleDescription</code></td><td><code>0..1</code></td><td><code>«atpUriDef, atpVariation»</code></td><td>Formale Referenz auf die Beschreibung des Zielmoduls via URI</td></tr><tr><td><code>BswModuleDescription</code></td><td>Komposition <code>+providedModeGroup</code></td><td><code>ModeDeclarationGroupPrototype</code></td><td><code>0..*</code></td><td><code>«atpVariation»</code></td><td>Vom Modul verwaltete / bereitgestellte Zustandsmodi</td></tr><tr><td><code>BswModuleDescription</code></td><td>Komposition <code>+requiredModeGroup</code></td><td><code>ModeDeclarationGroupPrototype</code></td><td><code>0..*</code></td><td><code>«atpVariation»</code></td><td>Vom Modul überwachte / benötigte Zustandsmodi</td></tr><tr><td><code>BswModuleDescription</code></td><td>Komposition <code>+releasedTrigger</code></td><td><code>Trigger</code></td><td><code>0..*</code></td><td><code>«atpVariation»</code></td><td>Geworfene Trigger für RTE/BswM</td></tr><tr><td><code>BswModuleDescription</code></td><td>Komposition <code>+requiredTrigger</code></td><td><code>Trigger</code></td><td><code>0..*</code></td><td><code>«atpVariation»</code></td><td>Konsumierte Trigger zur Aktivierung von Entities</td></tr><tr><td><code>BswModuleDescription</code></td><td>Assoziation <code>+providedClientServerEntry</code></td><td><code>BswModuleClientServerEntry</code></td><td><code>0..*</code></td><td><code>«atpVariation»</code></td><td>Vom Modul angebotene Client-Server-Operationen</td></tr><tr><td><code>BswModuleDescription</code></td><td>Assoziation <code>+requiredClientServerEntry</code></td><td><code>BswModuleClientServerEntry</code></td><td><code>0..*</code></td><td><code>«atpVariation»</code></td><td>Vom Modul angeforderte Client-Server-Operationen</td></tr><tr><td><code>BswModuleDescription</code></td><td>Assoziation <code>+providedData</code></td><td><code>VariableDataPrototype</code></td><td><code>0..*</code></td><td><code>«atpVariation»</code></td><td>Vom Modul bereitgestellte Datenprototypen</td></tr><tr><td><code>BswModuleDescription</code></td><td>Assoziation <code>+requiredData</code></td><td><code>VariableDataPrototype</code></td><td><code>0..*</code></td><td><code>«atpVariation»</code></td><td>Vom Modul benötigte Datenprototypen</td></tr><tr><td><code>BswModuleDescription</code></td><td>Komposition <code>+internalBehavior</code></td><td><code>BswInternalBehavior</code></td><td><code>0..*</code></td><td><code>«atpSplitable»</code></td><td>Internes Ausführungsverhalten (Split erlaubt Trennung über ARXML-Dateien)</td></tr></tbody></table></div>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Obgleich ein statisches Metamodell vorliegt, erzwingt die Struktur folgende dynamische Interaktionsmuster zur Laufzeit:</p>\n<ul class=\"fig-list\"><li><strong>Direkte C-Funktionsaufrufe und Callbacks:</strong>\n<ul class=\"fig-list\"><li><code>providedEntry</code> definiert Einstiegspunkte für synchrone Aufrufe (z. B. <code>CanIf_Transmit</code> aufgerufen durch <code>PduR</code>).\n</li><li><code>outgoingCallback</code> definiert Auslösepunkte für C-Callbacks nach außen (z. B. im Interrupt- oder ISR-Deferred-Kontext).\n</li></ul>\n</li><li><strong>Client-Server-Interaktion:</strong>\n<ul class=\"fig-list\"><li><code>providedClientServerEntry</code> und <code>requiredClientServerEntry</code> ermöglichen Client-Server-Aufrufe zwischen BSW-Modulen, parametriert über <code>isSynchronous</code> (blockierend vs. asynchron) und <code>isReentrant</code> (Wiedereintrittsfähigkeit).\n</li></ul>\n</li><li><strong>Datenbasierte Kommunikation:</strong>\n<ul class=\"fig-list\"><li>Datenaustausch über <code>providedData</code> und <code>requiredData</code> auf Basis von <code>VariableDataPrototype</code> ermöglicht standardisierten Wertefluss zwischen Modulen.\n</li></ul>\n</li><li><strong>Modulabhängigkeiten:</strong>\n<ul class=\"fig-list\"><li>Abhängigkeiten zu anderen Modulen werden in <code>BswModuleDependency</code> gekapselt und können über die Modul-ID (<code>targetModuleId</code>) sowie über eine direkte URI-Referenz (<code>targetModuleRef</code>) auf die Ziel-<code>BswModuleDescription</code> aufgelöst werden.\n</li></ul>\n</li><li><strong>Mode-Switching &amp; State-Propagation:</strong>\n<ul class=\"fig-list\"><li>Statusänderungen über <code>providedModeGroup</code> triggern Moduswechsel im BSW Mode Manager (<code>BswM</code>) oder in abhängigen Modulen (<code>requiredModeGroup</code>).\n</li></ul>\n</li><li><strong>Asynchrones Triggering:</strong>\n<ul class=\"fig-list\"><li>Ein <code>releasedTrigger</code> kann über den SchM/OS-Dispatcher ohne PDU-Payload eine Taskaktivierung oder die Ausführung verknüpfter BswSchedulableEntities auslösen (<code>requiredTrigger</code>).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>BSWMD-Erstellung (Treiber- &amp; Stack-Lieferanten):</strong>\n<ul class=\"fig-list\"><li>Jedes BSW-Modul liefert eine formale ARXML-Beschreibung mit <code>BswModuleDescription</code> als Wurzelelement.\n</li><li>Das Attribut <code>moduleId</code> ist optional (<code>[0..1]</code>), wodurch auch Bibliotheken oder komplexe Gerätetreiber ohne normierte Standard-Modul-ID beschrieben werden können. Ist eine Standard-Modul-ID vorhanden, muss sie der AUTOSAR-Spezifikation entsprechen.\n</li></ul>\n</li><li><strong>Modul-Referenzierung und Packaging:</strong>\n<ul class=\"fig-list\"><li>Die Modellierung von Abhängigkeiten über <code>BswModuleDependency</code> unterstützt neben <code>targetModuleId</code> die modellübergreifende Adressierung mittels <code>targetModuleRef</code> (<code>«atpUriDef»</code>), wodurch Verweise auf andere Pakete formal validierbar sind.\n</li><li>Durch <code>«atpSplitable»</code> an <code>internalBehavior</code>, <code>bswModuleDocumentation</code> und <code>bswModuleDependency</code> dürfen Modulbeschreibung und internes Verhalten in getrennten ARXML-Dateien ausgeliefert werden.\n</li><li><code>«atpVariation»</code> erlaubt Post-Build- oder Pre-Compile-Variantenbildung auf Ebene von C-Entries, Callbacks, Client-Server-Entries, Datenprototypen, Triggern und Moden über System-Constants.\n</li></ul>\n</li><li><strong>Generierung des Basic Software Schedulers (SchM):</strong>\n<ul class=\"fig-list\"><li>Die Verknüpfung von <code>BswModuleDescription</code> mit <code>BswInternalBehavior</code> steuert die Generierung der <code>SchM_&lt;Bsw&gt;.h</code>-Header (z. B. Exclusive Areas via <code>SchM_Enter_&lt;Mod&gt;_&lt;Area&gt;()</code> und zyklische Main-Functions via <code>SchM_ActMainFunction_&lt;Mod&gt;()</code>).\n</li></ul>\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-4e7618412e0e28e1", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Diagrammtyp:</strong> AUTOSAR M2-Metamodell-Ausschnitt als UML-Klassendiagramm (Strukturdiagramm).\n</li><li><strong>Architektur-Kontext:</strong> Definition der Wurzelebene des BSW Module Description Templates (BSWMDT, AUTOSAR Classic Platform R4.0.3).\n</li><li><strong>Funktionaler Zweck:</strong> Formale Spezifikation der äußeren Hülle eines Basissoftware-Moduls (<code>BswModuleDescription</code>). Dient als maschinenlesbarer Vertrag (ARXML) für den BSW- und RTE/SchM-Generator zur Definition von Funktionsschnittstellen (APIs/Callbacks), Modulabhängigkeiten, Mode- und Trigger-Interaktionen sowie als Anker für das interne Verhalten (<code>BswInternalBehavior</code>).\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Entitäten und Klassenhierarchie</h5>\n<ul class=\"fig-list\"><li><strong><code>BswModuleDescription</code></strong>\n<ul class=\"fig-list\"><li><em>Vererbung / Stereotypen:</em> <code>ARElement</code>, <code>AtpBlueprint</code>, <code>AtpBlueprintable</code>, <code>AtpStructureElement</code>.\n</li><li><em>Attribute:</em> <code>+ moduleId: PositiveInteger [0..1]</code> (Normierte AUTOSAR-BSW-Modul-ID).\n</li><li><em>Rolle:</em> Top-Level-Beschreibungscontainer für ein einzelnes BSW-Modul (Treiber, Stack, Service).\n</li></ul>\n</li><li><strong><code>BswModuleEntry</code></strong>\n<ul class=\"fig-list\"><li><em>Vererbung / Stereotypen:</em> <code>ARElement</code>, <code>AtpBlueprint</code>, <code>AtpBlueprintable</code>.\n</li><li><em>Rolle:</em> Repräsentiert eine C-Funktionssignatur (C-API-Funktion, Main-Function oder Callback) auf C-Quellcodeebene.\n</li></ul>\n</li><li><strong><code>BswModuleDependency</code></strong>\n<ul class=\"fig-list\"><li><em>Vererbung / Stereotypen:</em> <code>Identifiable</code>.\n</li><li><em>Attribute:</em> <code>+ targetModuleId: PositiveInteger [0..1]</code> (Modul-ID des Zielmoduls).\n</li><li><em>Rolle:</em> Kapselt die vertraglichen Schnittstellenanforderungen an ein anderes BSW-Modul.\n</li></ul>\n</li><li><strong><code>ModeDeclarationGroupPrototype</code></strong>\n<ul class=\"fig-list\"><li><em>Vererbung / Stereotypen:</em> <code>AtpPrototype</code>.\n</li><li><em>Attribute:</em> <code>+ swCalibrationAccess: SwCalibrationAccessEnum [0..1]</code>.\n</li><li><em>Rolle:</em> Prototyp einer Modus-Deklarationsgruppe zur Festlegung von BSW-Zustandsmodi.\n</li></ul>\n</li><li><strong><code>Trigger</code></strong>\n<ul class=\"fig-list\"><li><em>Vererbung / Stereotypen:</em> <code>AtpStructureElement</code>, <code>Identifiable</code>.\n</li><li><em>Attribute:</em> <code>+ swImplPolicy: SwImplPolicyEnum [0..1]</code>.\n</li><li><em>Rolle:</em> Ereignisquelle für asynchrone Prozessaktivierungen ohne Parameterübertragung.\n</li></ul>\n</li><li><strong><code>BswModuleClientServerEntry</code></strong>\n<ul class=\"fig-list\"><li><em>Vererbung / Stereotypen:</em> <code>Referrable</code>.\n</li><li><em>Attribute:</em> <code>+ isReentrant: Boolean [0..1]</code>, <code>+ isSynchronous: Boolean [0..1]</code>.\n</li><li><em>Rolle:</em> Kapselt eine Client-Server-Schnittstelle innerhalb des BSW inklusive Synchronitäts- und Reentrancy-Eigenschaften.\n</li></ul>\n</li><li><strong><code>VariableDataPrototype</code></strong>\n<ul class=\"fig-list\"><li><em>Vererbung / Stereotypen:</em> <code>AutosarDataPrototype</code>.\n</li><li><em>Rolle:</em> Repräsentiert typisierte Datenprototypen für datenbasierte Schnittstellen (Sender-Receiver bzw. Data Exchange).\n</li></ul>\n</li><li><strong><code>BswInternalBehavior</code></strong>\n<ul class=\"fig-list\"><li><em>Vererbung / Stereotypen:</em> <code>InternalBehavior</code>.\n</li><li><em>Rolle:</em> Kapselung von BSW-Schedulable-Entities, Exclusive Areas, BSW-Events und Task-Mappings.\n</li></ul>\n</li><li><strong><code>SwComponentDocumentation</code></strong>\n<ul class=\"fig-list\"><li><em>Archetyp:</em> Tag <code>A</code>.\n</li><li><em>Rolle:</em> Strukturierte technische Dokumentation des Moduls.\n</li></ul>\n</li></ul>\n<h5 class=\"fig-section-h5\">Beziehungen, Kardinalitäten und Stereotypen</h5>\n<div class=\"table-wrap\"><table class=\"fig-table\"><thead><tr><th>Quell-Element</th><th>Relation / Rolle</th><th>Ziel-Element</th><th>Kardinalität</th><th>Stereotypen</th><th>Semantik</th></tr></thead><tbody><tr><td><code>BswModuleDescription</code></td><td>Komposition <code>+bswModuleDocumentation</code></td><td><code>SwComponentDocumentation</code></td><td><code>0..1</code></td><td><code>«atpVariation, atpSplitable»</code></td><td>Dokumentationsanhang; varianten- und dateisplitfähig</td></tr><tr><td><code>BswModuleDescription</code></td><td>Assoziation <code>+providedEntry</code></td><td><code>BswModuleEntry</code></td><td><code>0..*</code></td><td><code>«atpVariation, atpSplitable»</code></td><td>Vom Modul implementierte und exportierte C-APIs; varianten- und dateisplitfähig</td></tr><tr><td><code>BswModuleDescription</code></td><td>Assoziation <code>+outgoingCallback</code></td><td><code>BswModuleEntry</code></td><td><code>0..*</code></td><td><code>«atpVariation, atpSplitable»</code></td><td>Vom Modul aktiv aufgerufene Callbacks nach außen; varianten- und dateisplitfähig</td></tr><tr><td><code>BswModuleDescription</code></td><td>Komposition <code>+bswModuleDependency</code></td><td><code>BswModuleDependency</code></td><td><code>0..*</code></td><td><code>«atpVariation, atpSplitable»</code></td><td>Deklarierte Abhängigkeit zu anderen BSW-Modulen</td></tr><tr><td><code>BswModuleDependency</code></td><td>Assoziation <code>+targetModuleRef</code></td><td><code>BswModuleDescription</code></td><td><code>0..1</code></td><td><code>«atpUriDef, atpVariation»</code></td><td>Formale Referenz auf die Beschreibung des Zielmoduls via URI</td></tr><tr><td><code>BswModuleDescription</code></td><td>Komposition <code>+providedModeGroup</code></td><td><code>ModeDeclarationGroupPrototype</code></td><td><code>0..*</code></td><td><code>«atpVariation, atpSplitable»</code></td><td>Vom Modul verwaltete / bereitgestellte Zustandsmodi; varianten- und dateisplitfähig</td></tr><tr><td><code>BswModuleDescription</code></td><td>Komposition <code>+requiredModeGroup</code></td><td><code>ModeDeclarationGroupPrototype</code></td><td><code>0..*</code></td><td><code>«atpVariation, atpSplitable»</code></td><td>Vom Modul überwachte / benötigte Zustandsmodi; varianten- und dateisplitfähig</td></tr><tr><td><code>BswModuleDescription</code></td><td>Komposition <code>+releasedTrigger</code></td><td><code>Trigger</code></td><td><code>0..*</code></td><td><code>«atpVariation, atpSplitable»</code></td><td>Geworfene Trigger für RTE/BswM; varianten- und dateisplitfähig</td></tr><tr><td><code>BswModuleDescription</code></td><td>Komposition <code>+requiredTrigger</code></td><td><code>Trigger</code></td><td><code>0..*</code></td><td><code>«atpVariation, atpSplitable»</code></td><td>Konsumierte Trigger zur Aktivierung von Entities; varianten- und dateisplitfähig</td></tr><tr><td><code>BswModuleDescription</code></td><td>Assoziation <code>+providedClientServerEntry</code></td><td><code>BswModuleClientServerEntry</code></td><td><code>0..*</code></td><td><code>«atpVariation, atpSplitable»</code></td><td>Vom Modul angebotene Client-Server-Operationen; varianten- und dateisplitfähig</td></tr><tr><td><code>BswModuleDescription</code></td><td>Assoziation <code>+requiredClientServerEntry</code></td><td><code>BswModuleClientServerEntry</code></td><td><code>0..*</code></td><td><code>«atpVariation, atpSplitable»</code></td><td>Vom Modul angeforderte Client-Server-Operationen; varianten- und dateisplitfähig</td></tr><tr><td><code>BswModuleDescription</code></td><td>Assoziation <code>+providedData</code></td><td><code>VariableDataPrototype</code></td><td><code>0..*</code></td><td><code>«atpVariation, atpSplitable»</code></td><td>Vom Modul bereitgestellte Datenprototypen; varianten- und dateisplitfähig</td></tr><tr><td><code>BswModuleDescription</code></td><td>Assoziation <code>+requiredData</code></td><td><code>VariableDataPrototype</code></td><td><code>0..*</code></td><td><code>«atpVariation, atpSplitable»</code></td><td>Vom Modul benötigte Datenprototypen; varianten- und dateisplitfähig</td></tr><tr><td><code>BswModuleDescription</code></td><td>Komposition <code>+internalBehavior</code></td><td><code>BswInternalBehavior</code></td><td><code>0..*</code></td><td><code>«atpSplitable»</code></td><td>Internes Ausführungsverhalten (Split erlaubt Trennung über ARXML-Dateien)</td></tr></tbody></table></div>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Obgleich ein statisches Metamodell vorliegt, erzwingt die Struktur folgende dynamische Interaktionsmuster zur Laufzeit:</p>\n<ul class=\"fig-list\"><li><strong>Direkte C-Funktionsaufrufe und Callbacks:</strong>\n<ul class=\"fig-list\"><li><code>providedEntry</code> definiert Einstiegspunkte für synchrone Aufrufe (z. B. <code>CanIf_Transmit</code> aufgerufen durch <code>PduR</code>).\n</li><li><code>outgoingCallback</code> definiert Auslösepunkte für C-Callbacks nach außen (z. B. im Interrupt- oder ISR-Deferred-Kontext).\n</li></ul>\n</li><li><strong>Client-Server-Interaktion:</strong>\n<ul class=\"fig-list\"><li><code>providedClientServerEntry</code> und <code>requiredClientServerEntry</code> ermöglichen Client-Server-Aufrufe zwischen BSW-Modulen, parametriert über <code>isSynchronous</code> (blockierend vs. asynchron) und <code>isReentrant</code> (Wiedereintrittsfähigkeit).\n</li></ul>\n</li><li><strong>Datenbasierte Kommunikation:</strong>\n<ul class=\"fig-list\"><li>Datenaustausch über <code>providedData</code> und <code>requiredData</code> auf Basis von <code>VariableDataPrototype</code> ermöglicht standardisierten Wertefluss zwischen Modulen.\n</li></ul>\n</li><li><strong>Modulabhängigkeiten:</strong>\n<ul class=\"fig-list\"><li>Abhängigkeiten zu anderen Modulen werden in <code>BswModuleDependency</code> gekapselt und können über die Modul-ID (<code>targetModuleId</code>) sowie über eine direkte URI-Referenz (<code>targetModuleRef</code>) auf die Ziel-<code>BswModuleDescription</code> aufgelöst werden.\n</li></ul>\n</li><li><strong>Mode-Switching &amp; State-Propagation:</strong>\n<ul class=\"fig-list\"><li>Statusänderungen über <code>providedModeGroup</code> triggern Moduswechsel im BSW Mode Manager (<code>BswM</code>) oder in abhängigen Modulen (<code>requiredModeGroup</code>).\n</li></ul>\n</li><li><strong>Asynchrones Triggering:</strong>\n<ul class=\"fig-list\"><li>Ein <code>releasedTrigger</code> kann über den SchM/OS-Dispatcher ohne PDU-Payload eine Taskaktivierung oder die Ausführung verknüpfter BswSchedulableEntities auslösen (<code>requiredTrigger</code>).\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>BSWMD-Erstellung (Treiber- &amp; Stack-Lieferanten):</strong>\n<ul class=\"fig-list\"><li>Jedes BSW-Modul liefert eine formale ARXML-Beschreibung mit <code>BswModuleDescription</code> als Wurzelelement.\n</li><li>Das Attribut <code>moduleId</code> ist optional (<code>[0..1]</code>), wodurch auch Bibliotheken oder komplexe Gerätetreiber ohne normierte Standard-Modul-ID beschrieben werden können. Ist eine Standard-Modul-ID vorhanden, muss sie der AUTOSAR-Spezifikation entsprechen.\n</li></ul>\n</li><li><strong>Metamodell-Regeln für das Packaging und Splitfähigkeit:</strong>\n<ul class=\"fig-list\"><li>Sämtliche Port- und Schnittstellen-Assoziationen der <code>BswModuleDescription</code> (<code>providedEntry</code>, <code>outgoingCallback</code>, <code>providedModeGroup</code>, <code>requiredModeGroup</code>, <code>releasedTrigger</code>, <code>requiredTrigger</code>, <code>providedClientServerEntry</code>, <code>requiredClientServerEntry</code>, <code>providedData</code>, <code>requiredData</code>) sowie <code>bswModuleDocumentation</code> und <code>bswModuleDependency</code> besitzen den Stereotyp <code>«atpSplitable»</code>. Dadurch können Schnittstellendefinitionen granular über mehrere ARXML-Dateien bzw. Lieferpakete aufgeteilt und zusammengeführt werden.\n</li><li>Die Verknüpfung <code>targetModuleRef</code> an <code>BswModuleDependency</code> besitzt den Stereotyp <code>«atpUriDef, atpVariation»</code> zur URI-basierten Moduladressierung.\n</li><li>Durchgängige Unterstützung von <code>«atpVariation»</code> erlaubt Variantenbildung für Schnittstellen, Abhängigkeiten, Trigger und Moden über System-Constants.\n</li></ul>\n</li><li><strong>Generierung des Basic Software Schedulers (SchM):</strong>\n<ul class=\"fig-list\"><li>Die Verknüpfung von <code>BswModuleDescription</code> mit <code>BswInternalBehavior</code> steuert die Generierung der <code>SchM_&lt;Bsw&gt;.h</code>-Header (z. B. Exclusive Areas via <code>SchM_Enter_&lt;Mod&gt;_&lt;Area&gt;()</code> und zyklische Main-Functions via <code>SchM_ActMainFunction_&lt;Mod&gt;()</code>).\n</li></ul>\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-2a2380d146215670", "releases": ["R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Diagrammtyp:</strong> AUTOSAR M2-Metamodell-Ausschnitt als UML-Klassendiagramm (Strukturdiagramm).\n</li><li><strong>Architektur-Kontext:</strong> Definition der Wurzelebene des BSW Module Description Templates (BSWMDT, AUTOSAR Classic Platform R4.0.3).\n</li><li><strong>Funktionaler Zweck:</strong> Formale Spezifikation der äußeren Hülle eines Basissoftware-Moduls (<code>BswModuleDescription</code>). Dient als maschinenlesbarer Vertrag (ARXML) für den BSW- und RTE/SchM-Generator zur Definition von Funktionsschnittstellen (APIs/Callbacks), Modulabhängigkeiten, Mode- und Trigger-Interaktionen sowie als Anker für das interne Verhalten (<code>BswInternalBehavior</code>).\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Entitäten und Klassenhierarchie</h5>\n<ul class=\"fig-list\"><li><strong><code>BswModuleDescription</code></strong>\n<ul class=\"fig-list\"><li><em>Vererbung / Stereotypen:</em> <code>ARElement</code>, <code>AtpBlueprint</code>, <code>AtpBlueprintable</code>, <code>AtpStructureElement</code>.\n</li><li><em>Attribute:</em> <code>+ moduleId: PositiveInteger [0..1]</code> (Normierte AUTOSAR-BSW-Modul-ID).\n</li><li><em>Rolle:</em> Top-Level-Beschreibungscontainer für ein einzelnes BSW-Modul (Treiber, Stack, Service).\n</li></ul>\n</li><li><strong><code>BswModuleEntry</code></strong>\n<ul class=\"fig-list\"><li><em>Vererbung / Stereotypen:</em> <code>ARElement</code>, <code>AtpBlueprint</code>, <code>AtpBlueprintable</code>.\n</li><li><em>Rolle:</em> Repräsentiert eine C-Funktionssignatur (C-API-Funktion, Main-Function oder Callback) auf C-Quellcodeebene.\n</li></ul>\n</li><li><strong><code>BswModuleDependency</code></strong>\n<ul class=\"fig-list\"><li><em>Vererbung / Stereotypen:</em> <code>Identifiable</code>.\n</li><li><em>Attribute:</em> <code>+ targetModuleId: PositiveInteger [0..1]</code> (Modul-ID des Zielmoduls).\n</li><li><em>Rolle:</em> Kapselt die vertraglichen Schnittstellenanforderungen an ein anderes BSW-Modul.\n</li></ul>\n</li><li><strong><code>ModeDeclarationGroupPrototype</code></strong>\n<ul class=\"fig-list\"><li><em>Vererbung / Stereotypen:</em> <code>AtpPrototype</code>.\n</li><li><em>Attribute:</em> <code>+ swCalibrationAccess: SwCalibrationAccessEnum [0..1]</code>.\n</li><li><em>Rolle:</em> Prototyp einer Modus-Deklarationsgruppe zur Festlegung von BSW-Zustandsmodi.\n</li></ul>\n</li><li><strong><code>Trigger</code></strong>\n<ul class=\"fig-list\"><li><em>Vererbung / Stereotypen:</em> <code>AtpStructureElement</code>, <code>Identifiable</code>.\n</li><li><em>Attribute:</em> <code>+ swImplPolicy: SwImplPolicyEnum [0..1]</code>.\n</li><li><em>Rolle:</em> Ereignisquelle für asynchrone Prozessaktivierungen ohne Parameterübertragung.\n</li></ul>\n</li><li><strong><code>BswModuleClientServerEntry</code></strong>\n<ul class=\"fig-list\"><li><em>Vererbung / Stereotypen:</em> <code>Referrable</code>.\n</li><li><em>Attribute:</em> <code>+ isReentrant: Boolean [0..1]</code>, <code>+ isSynchronous: Boolean [0..1]</code>.\n</li><li><em>Rolle:</em> Kapselt eine Client-Server-Schnittstelle innerhalb des BSW inklusive Synchronitäts- und Reentrancy-Eigenschaften.\n</li></ul>\n</li><li><strong><code>VariableDataPrototype</code></strong>\n<ul class=\"fig-list\"><li><em>Vererbung / Stereotypen:</em> <code>AutosarDataPrototype</code>.\n</li><li><em>Rolle:</em> Repräsentiert typisierte Datenprototypen für datenbasierte Schnittstellen sowie für per-Instance-Memory.\n</li></ul>\n</li><li><strong><code>BswInternalBehavior</code></strong>\n<ul class=\"fig-list\"><li><em>Vererbung / Stereotypen:</em> <code>InternalBehavior</code>.\n</li><li><em>Rolle:</em> Kapselung von BSW-Schedulable-Entities, Exclusive Areas, BSW-Events, Task-Mappings und instanzspezifischem Speicher.\n</li></ul>\n</li><li><strong><code>SwComponentDocumentation</code></strong>\n<ul class=\"fig-list\"><li><em>Archetyp:</em> Tag <code>A</code>.\n</li><li><em>Rolle:</em> Strukturierte technische Dokumentation des Moduls.\n</li></ul>\n</li></ul>\n<h5 class=\"fig-section-h5\">Beziehungen, Kardinalitäten und Stereotypen</h5>\n<div class=\"table-wrap\"><table class=\"fig-table\"><thead><tr><th>Quell-Element</th><th>Relation / Rolle</th><th>Ziel-Element</th><th>Kardinalität</th><th>Stereotypen</th><th>Semantik</th></tr></thead><tbody><tr><td><code>BswModuleDescription</code></td><td>Komposition <code>+bswModuleDocumentation</code></td><td><code>SwComponentDocumentation</code></td><td><code>0..1</code></td><td><code>«atpVariation, atpSplitable»</code></td><td>Dokumentationsanhang; varianten- und dateisplitfähig</td></tr><tr><td><code>BswModuleDescription</code></td><td>Assoziation <code>+implementedEntry</code></td><td><code>BswModuleEntry</code></td><td><code>0..*</code></td><td><code>«atpVariation, atpSplitable»</code></td><td>Vom Modul implementierte C-APIs; varianten- und dateisplitfähig</td></tr><tr><td><code>BswModuleDescription</code></td><td>Assoziation <code>+expectedEntry</code></td><td><code>BswModuleEntry</code></td><td><code>0..*</code></td><td><code>«atpVariation, atpSplitable»</code></td><td>Vom Modul erwartete C-APIs bzw. Callbacks; varianten- und dateisplitfähig</td></tr><tr><td><code>BswModuleDescription</code></td><td>Komposition <code>+bswModuleDependency</code></td><td><code>BswModuleDependency</code></td><td><code>0..*</code></td><td><code>«atpVariation, atpSplitable»</code></td><td>Deklarierte Abhängigkeit zu anderen BSW-Modulen</td></tr><tr><td><code>BswModuleDependency</code></td><td>Assoziation <code>+targetModuleRef</code></td><td><code>BswModuleDescription</code></td><td><code>0..1</code></td><td><code>«atpUriDef, atpVariation»</code></td><td>Formale Referenz auf die Beschreibung des Zielmoduls via URI</td></tr><tr><td><code>BswModuleDescription</code></td><td>Komposition <code>+providedModeGroup</code></td><td><code>ModeDeclarationGroupPrototype</code></td><td><code>0..*</code></td><td><code>«atpVariation, atpSplitable»</code></td><td>Vom Modul verwaltete / bereitgestellte Zustandsmodi; varianten- und dateisplitfähig</td></tr><tr><td><code>BswModuleDescription</code></td><td>Komposition <code>+requiredModeGroup</code></td><td><code>ModeDeclarationGroupPrototype</code></td><td><code>0..*</code></td><td><code>«atpVariation, atpSplitable»</code></td><td>Vom Modul überwachte / benötigte Zustandsmodi; varianten- und dateisplitfähig</td></tr><tr><td><code>BswModuleDescription</code></td><td>Komposition <code>+releasedTrigger</code></td><td><code>Trigger</code></td><td><code>0..*</code></td><td><code>«atpVariation, atpSplitable»</code></td><td>Geworfene Trigger für RTE/BswM; varianten- und dateisplitfähig</td></tr><tr><td><code>BswModuleDescription</code></td><td>Komposition <code>+requiredTrigger</code></td><td><code>Trigger</code></td><td><code>0..*</code></td><td><code>«atpVariation, atpSplitable»</code></td><td>Konsumierte Trigger zur Aktivierung von Entities; varianten- und dateisplitfähig</td></tr><tr><td><code>BswModuleDescription</code></td><td>Assoziation <code>+providedClientServerEntry</code></td><td><code>BswModuleClientServerEntry</code></td><td><code>0..*</code></td><td><code>«atpVariation, atpSplitable»</code></td><td>Vom Modul angebotene Client-Server-Operationen; varianten- und dateisplitfähig</td></tr><tr><td><code>BswModuleDescription</code></td><td>Assoziation <code>+requiredClientServerEntry</code></td><td><code>BswModuleClientServerEntry</code></td><td><code>0..*</code></td><td><code>«atpVariation, atpSplitable»</code></td><td>Vom Modul angeforderte Client-Server-Operationen; varianten- und dateisplitfähig</td></tr><tr><td><code>BswModuleDescription</code></td><td>Assoziation <code>+providedData</code></td><td><code>VariableDataPrototype</code></td><td><code>0..*</code></td><td><code>«atpVariation, atpSplitable»</code></td><td>Vom Modul bereitgestellte Datenprototypen; varianten- und dateisplitfähig</td></tr><tr><td><code>BswModuleDescription</code></td><td>Assoziation <code>+requiredData</code></td><td><code>VariableDataPrototype</code></td><td><code>0..*</code></td><td><code>«atpVariation, atpSplitable»</code></td><td>Vom Modul benötigte Datenprototypen; varianten- und dateisplitfähig</td></tr><tr><td><code>BswModuleDescription</code></td><td>Komposition <code>+internalBehavior</code></td><td><code>BswInternalBehavior</code></td><td><code>0..*</code></td><td><code>«atpSplitable»</code></td><td>Internes Ausführungsverhalten (Split erlaubt Trennung über ARXML-Dateien)</td></tr><tr><td><code>BswInternalBehavior</code></td><td>Komposition <code>+arTypedPerInstanceMemory</code></td><td><code>VariableDataPrototype</code></td><td><code>0..*</code></td><td><code>«atpVariation, atpSplitable»</code></td><td>Instanzspezifischer Speicher für das interne Verhalten; varianten- und dateisplitfähig</td></tr></tbody></table></div>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Obgleich ein statisches Metamodell vorliegt, erzwingt die Struktur folgende dynamische Interaktionsmuster zur Laufzeit:</p>\n<ul class=\"fig-list\"><li><strong>Funktionsaufrufe und Schnittstellenimplementierung:</strong>\n<ul class=\"fig-list\"><li><code>implementedEntry</code> definiert die vom BSW-Modul konkret bereitgestellten C-Funktionseinstiegspunkte (APIs, Main-Functions).\n</li><li><code>expectedEntry</code> deklariert die vom Modul für den Betrieb vorausgesetzten externen C-Funktionen bzw. Callback-Signaturen.\n</li></ul>\n</li><li><strong>Client-Server-Interaktion:</strong>\n<ul class=\"fig-list\"><li><code>providedClientServerEntry</code> und <code>requiredClientServerEntry</code> steuern Client-Server-Aufrufe, parametriert über <code>isSynchronous</code> (blockierendes vs. asynchrones Verhalten) und <code>isReentrant</code> (Wiedereintrittsfähigkeit).\n</li></ul>\n</li><li><strong>Datenbasierte Kommunikation und interner Speicher:</strong>\n<ul class=\"fig-list\"><li><code>providedData</code> und <code>requiredData</code> definieren den Datenaustausch mit anderen BSW-Modulen oder Software-Components via <code>VariableDataPrototype</code>.\n</li><li><code>arTypedPerInstanceMemory</code> stellt typisierten Speicher pro Modulinstanz bereit, auf den die Entities des <code>BswInternalBehavior</code> zur Laufzeit zugreifen.\n</li></ul>\n</li><li><strong>Modulabhängigkeiten:</strong>\n<ul class=\"fig-list\"><li><code>BswModuleDependency</code> verknüpft das Modul über <code>targetModuleId</code> bzw. über eine URI-Referenz (<code>targetModuleRef</code>) mit der abhängigen <code>BswModuleDescription</code>.\n</li></ul>\n</li><li><strong>Mode-Switching &amp; State-Propagation:</strong>\n<ul class=\"fig-list\"><li>Moduswechsel werden über <code>providedModeGroup</code> an den BSW Mode Manager (<code>BswM</code>) propagiert oder über <code>requiredModeGroup</code> konsumiert.\n</li></ul>\n</li><li><strong>Asynchrones Triggering:</strong>\n<ul class=\"fig-list\"><li>Ereignisse werden über <code>releasedTrigger</code> abgesetzt und lösen über <code>requiredTrigger</code> verknüpfte Abarbeitungsfolgen im SchM/OS aus.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>BSWMD-Erstellung (Treiber- &amp; Stack-Lieferanten):</strong>\n<ul class=\"fig-list\"><li>Jedes BSW-Modul liefert eine formale ARXML-Beschreibung mit <code>BswModuleDescription</code> als Wurzelelement.\n</li><li>C-Funktionen werden über <code>implementedEntry</code> (Export) und <code>expectedEntry</code> (Import) modelliert, wodurch die Funktionsschnittstellen für den SchM- und RTE-Generator eindeutig deklariert werden.\n</li><li>Das Attribut <code>moduleId</code> ist optional (<code>[0..1]</code>), um standardisierte sowie herstellerspezifische Module und Bibliotheken abbilden zu können.\n</li></ul>\n</li><li><strong>Packaging, Variantenbildung und Per-Instance-Memory:</strong>\n<ul class=\"fig-list\"><li>Sämtliche Schnittstellenrollen an <code>BswModuleDescription</code> sowie <code>arTypedPerInstanceMemory</code> an <code>BswInternalBehavior</code> besitzen die Stereotypen <code>«atpVariation, atpSplitable»</code>. Dies erlaubt sowohl feingranulare Aufteilung über mehrere ARXML-Dateien als auch Variantenbindung zur Build- bzw. Post-Build-Zeit.\n</li><li><code>arTypedPerInstanceMemory</code> ermöglicht die AUTOSAR-konforme Typisierung von instanzspezifischem Speicher (PIM) direkt über <code>VariableDataPrototype</code> im internen Verhalten.\n</li></ul>\n</li><li><strong>Generierung des Basic Software Schedulers (SchM):</strong>\n<ul class=\"fig-list\"><li>Die Verknüpfung von <code>BswModuleDescription</code> mit <code>BswInternalBehavior</code> steuert die Generierung der <code>SchM_&lt;Bsw&gt;.h</code>-Header (z. B. Exclusive Areas via <code>SchM_Enter_&lt;Mod&gt;_&lt;Area&gt;()</code> und zyklische Main-Functions via <code>SchM_ActMainFunction_&lt;Mod&gt;()</code>).\n</li></ul>\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-80fe9df33049322e", "releases": ["R18-10_R4.4.0_R1.5.0", "R19-11", "R20-11", "R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Diagrammtyp:</strong> AUTOSAR M2-Metamodell-Ausschnitt als UML-Klassendiagramm (Strukturdiagramm).\n</li><li><strong>Architektur-Kontext:</strong> Definition der Wurzelebene des BSW Module Description Templates (BSWMDT, AUTOSAR Classic Platform R4.0.3).\n</li><li><strong>Funktionaler Zweck:</strong> Formale Spezifikation der äußeren Hülle eines Basissoftware-Moduls (<code>BswModuleDescription</code>). Dient als maschinenlesbarer Vertrag (ARXML) für den BSW- und RTE/SchM-Generator zur Definition von Funktionsschnittstellen (APIs/Callbacks), Modulabhängigkeiten, Mode- und Trigger-Interaktionen sowie als Anker für das interne Verhalten (<code>BswInternalBehavior</code>).\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Entitäten und Klassenhierarchie</h5>\n<ul class=\"fig-list\"><li><strong><code>BswModuleDescription</code></strong>\n<ul class=\"fig-list\"><li><em>Vererbung / Stereotypen:</em> <code>ARElement</code>, <code>AtpBlueprint</code>, <code>AtpBlueprintable</code>, <code>AtpStructureElement</code>.\n</li><li><em>Attribute:</em> <code>+ moduleId: PositiveInteger [0..1]</code> (Normierte AUTOSAR-BSW-Modul-ID).\n</li><li><em>Rolle:</em> Top-Level-Beschreibungscontainer für ein einzelnes BSW-Modul (Treiber, Stack, Service).\n</li></ul>\n</li><li><strong><code>BswModuleEntry</code></strong>\n<ul class=\"fig-list\"><li><em>Vererbung / Stereotypen:</em> <code>ARElement</code>, <code>AtpBlueprint</code>, <code>AtpBlueprintable</code>.\n</li><li><em>Rolle:</em> Repräsentiert eine C-Funktionssignatur (C-API-Funktion, Main-Function oder Callback) auf C-Quellcodeebene.\n</li></ul>\n</li><li><strong><code>BswModuleDependency</code></strong>\n<ul class=\"fig-list\"><li><em>Vererbung / Stereotypen:</em> <code>Identifiable</code>.\n</li><li><em>Attribute:</em> <code>+ targetModuleId: PositiveInteger [0..1]</code> (Modul-ID des Zielmoduls).\n</li><li><em>Rolle:</em> Kapselt die vertraglichen Schnittstellenanforderungen an ein anderes BSW-Modul.\n</li></ul>\n</li><li><strong><code>ModeDeclarationGroupPrototype</code></strong>\n<ul class=\"fig-list\"><li><em>Vererbung / Stereotypen:</em> <code>AtpPrototype</code>.\n</li><li><em>Attribute:</em> <code>+ swCalibrationAccess: SwCalibrationAccessEnum [0..1]</code>.\n</li><li><em>Rolle:</em> Prototyp einer Modus-Deklarationsgruppe zur Festlegung von BSW-Zustandsmodi.\n</li></ul>\n</li><li><strong><code>Trigger</code></strong>\n<ul class=\"fig-list\"><li><em>Vererbung / Stereotypen:</em> <code>AtpStructureElement</code>, <code>Identifiable</code>.\n</li><li><em>Attribute:</em> <code>+ swImplPolicy: SwImplPolicyEnum [0..1]</code>.\n</li><li><em>Rolle:</em> Ereignisquelle für asynchrone Prozessaktivierungen ohne Parameterübertragung.\n</li></ul>\n</li><li><strong><code>BswModuleClientServerEntry</code></strong>\n<ul class=\"fig-list\"><li><em>Vererbung / Stereotypen:</em> <code>Referrable</code>.\n</li><li><em>Attribute:</em> <code>+ isReentrant: Boolean [0..1]</code>, <code>+ isSynchronous: Boolean [0..1]</code>.\n</li><li><em>Rolle:</em> Kapselt eine Client-Server-Schnittstelle innerhalb des BSW inklusive Synchronitäts- und Reentrancy-Eigenschaften.\n</li></ul>\n</li><li><strong><code>VariableDataPrototype</code></strong>\n<ul class=\"fig-list\"><li><em>Vererbung / Stereotypen:</em> <code>AutosarDataPrototype</code>.\n</li><li><em>Rolle:</em> Repräsentiert typisierte Datenprototypen für datenbasierte Schnittstellen sowie für per-Instance-Memory.\n</li></ul>\n</li><li><strong><code>BswInternalBehavior</code></strong>\n<ul class=\"fig-list\"><li><em>Vererbung / Stereotypen:</em> <code>InternalBehavior</code>.\n</li><li><em>Rolle:</em> Kapselung von BSW-Schedulable-Entities, Exclusive Areas, BSW-Events, Task-Mappings und instanzspezifischem Speicher.\n</li></ul>\n</li><li><strong><code>SwComponentDocumentation</code></strong>\n<ul class=\"fig-list\"><li><em>Archetyp:</em> Tag <code>A</code>.\n</li><li><em>Rolle:</em> Strukturierte technische Dokumentation des Moduls.\n</li></ul>\n</li></ul>\n<h5 class=\"fig-section-h5\">Beziehungen, Kardinalitäten und Stereotypen</h5>\n<div class=\"table-wrap\"><table class=\"fig-table\"><thead><tr><th>Quell-Element</th><th>Relation / Rolle</th><th>Ziel-Element</th><th>Kardinalität</th><th>Stereotypen</th><th>Semantik</th></tr></thead><tbody><tr><td><code>BswModuleDescription</code></td><td>Komposition <code>+bswModuleDocumentation</code></td><td><code>SwComponentDocumentation</code></td><td><code>0..1</code></td><td><code>«atpVariation, atpSplitable»</code></td><td>Dokumentationsanhang; varianten- und dateisplitfähig</td></tr><tr><td><code>BswModuleDescription</code></td><td>Assoziation <code>+implementedEntry</code></td><td><code>BswModuleEntry</code></td><td><code>0..*</code></td><td><code>«atpVariation, atpSplitable»</code></td><td>Vom Modul implementierte C-APIs; varianten- und dateisplitfähig</td></tr><tr><td><code>BswModuleDescription</code></td><td>Assoziation <code>+expectedEntry</code></td><td><code>BswModuleEntry</code></td><td><code>0..*</code></td><td><code>«atpVariation, atpSplitable»</code></td><td>Vom Modul erwartete C-APIs bzw. Callbacks; varianten- und dateisplitfähig</td></tr><tr><td><code>BswModuleDescription</code></td><td>Komposition <code>+bswModuleDependency</code></td><td><code>BswModuleDependency</code></td><td><code>0..*</code></td><td><code>«atpVariation, atpSplitable»</code></td><td>Deklarierte Abhängigkeit zu anderen BSW-Modulen</td></tr><tr><td><code>BswModuleDependency</code></td><td>Assoziation <code>+targetModuleRef</code></td><td><code>BswModuleDescription</code></td><td><code>0..1</code></td><td><code>«atpUriDef, atpVariation»</code></td><td>Formale Referenz auf die Beschreibung des Zielmoduls via URI</td></tr><tr><td><code>BswModuleDescription</code></td><td>Komposition <code>+providedModeGroup</code></td><td><code>ModeDeclarationGroupPrototype</code></td><td><code>0..*</code></td><td><code>«atpVariation, atpSplitable»</code></td><td>Vom Modul verwaltete / bereitgestellte Zustandsmodi; varianten- und dateisplitfähig</td></tr><tr><td><code>BswModuleDescription</code></td><td>Komposition <code>+requiredModeGroup</code></td><td><code>ModeDeclarationGroupPrototype</code></td><td><code>0..*</code></td><td><code>«atpVariation, atpSplitable»</code></td><td>Vom Modul überwachte / benötigte Zustandsmodi; varianten- und dateisplitfähig</td></tr><tr><td><code>BswModuleDescription</code></td><td>Komposition <code>+releasedTrigger</code></td><td><code>Trigger</code></td><td><code>0..*</code></td><td><code>«atpVariation, atpSplitable»</code></td><td>Geworfene Trigger für RTE/BswM; varianten- und dateisplitfähig</td></tr><tr><td><code>BswModuleDescription</code></td><td>Komposition <code>+requiredTrigger</code></td><td><code>Trigger</code></td><td><code>0..*</code></td><td><code>«atpVariation, atpSplitable»</code></td><td>Konsumierte Trigger zur Aktivierung von Entities; varianten- und dateisplitfähig</td></tr><tr><td><code>BswModuleDescription</code></td><td>Assoziation <code>+providedClientServerEntry</code></td><td><code>BswModuleClientServerEntry</code></td><td><code>0..*</code></td><td><code>«atpVariation, atpSplitable»</code></td><td>Vom Modul angebotene Client-Server-Operationen; varianten- und dateisplitfähig</td></tr><tr><td><code>BswModuleDescription</code></td><td>Assoziation <code>+requiredClientServerEntry</code></td><td><code>BswModuleClientServerEntry</code></td><td><code>0..*</code></td><td><code>«atpVariation, atpSplitable»</code></td><td>Vom Modul angeforderte Client-Server-Operationen; varianten- und dateisplitfähig</td></tr><tr><td><code>BswModuleDescription</code></td><td>Assoziation <code>+providedData</code></td><td><code>VariableDataPrototype</code></td><td><code>0..*</code></td><td><code>«atpVariation, atpSplitable»</code></td><td>Vom Modul bereitgestellte Datenprototypen; varianten- und dateisplitfähig</td></tr><tr><td><code>BswModuleDescription</code></td><td>Assoziation <code>+requiredData</code></td><td><code>VariableDataPrototype</code></td><td><code>0..*</code></td><td><code>«atpVariation, atpSplitable»</code></td><td>Vom Modul benötigte Datenprototypen; varianten- und dateisplitfähig</td></tr><tr><td><code>BswModuleDescription</code></td><td>Komposition <code>+internalBehavior</code></td><td><code>BswInternalBehavior</code></td><td><code>0..*</code></td><td><code>«atpSplitable»</code></td><td>Internes Ausführungsverhalten (Split erlaubt Trennung über ARXML-Dateien)</td></tr><tr><td><code>BswInternalBehavior</code></td><td>Komposition <code>+arTypedPerInstanceMemory</code></td><td><code>VariableDataPrototype</code></td><td><code>0..*</code></td><td><code>«atpVariation, atpSplitable»</code></td><td>Instanzspezifischer Speicher für das interne Verhalten; varianten- und dateisplitfähig</td></tr></tbody></table></div>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Obgleich ein statisches Metamodell vorliegt, erzwingt die Struktur folgende dynamische Interaktionsmuster zur Laufzeit:</p>\n<ul class=\"fig-list\"><li><strong>Funktionsaufrufe und Schnittstellenimplementierung:</strong>\n<ul class=\"fig-list\"><li><code>implementedEntry</code> definiert die vom BSW-Modul konkret bereitgestellten C-Funktionseinstiegspunkte (APIs, Main-Functions).\n</li><li><code>expectedEntry</code> deklariert die vom Modul für den Betrieb vorausgesetzten externen C-Funktionen bzw. Callback-Signaturen.\n</li></ul>\n</li><li><strong>Client-Server-Interaktion:</strong>\n<ul class=\"fig-list\"><li><code>providedClientServerEntry</code> und <code>requiredClientServerEntry</code> steuern Client-Server-Aufrufe, parametriert über <code>isSynchronous</code> (blockierendes vs. asynchrones Verhalten) und <code>isReentrant</code> (Wiedereintrittsfähigkeit).\n</li></ul>\n</li><li><strong>Datenbasierte Kommunikation und interner Speicher:</strong>\n<ul class=\"fig-list\"><li><code>providedData</code> und <code>requiredData</code> definieren den Datenaustausch mit anderen BSW-Modulen oder Software-Components via <code>VariableDataPrototype</code>.\n</li><li><code>arTypedPerInstanceMemory</code> stellt typisierten Speicher pro Modulinstanz bereit, auf den die Entities des <code>BswInternalBehavior</code> zur Laufzeit zugreifen.\n</li></ul>\n</li><li><strong>Modulabhängigkeiten:</strong>\n<ul class=\"fig-list\"><li><code>BswModuleDependency</code> verknüpft das Modul über <code>targetModuleId</code> bzw. über eine URI-Referenz (<code>targetModuleRef</code>) mit der abhängigen <code>BswModuleDescription</code>.\n</li></ul>\n</li><li><strong>Mode-Switching &amp; State-Propagation:</strong>\n<ul class=\"fig-list\"><li>Moduswechsel werden über <code>providedModeGroup</code> an den BSW Mode Manager (<code>BswM</code>) propagiert oder über <code>requiredModeGroup</code> konsumiert.\n</li></ul>\n</li><li><strong>Asynchrones Triggering:</strong>\n<ul class=\"fig-list\"><li>Ereignisse werden über <code>releasedTrigger</code> abgesetzt und lösen über <code>requiredTrigger</code> verknüpfte Abarbeitungsfolgen im SchM/OS aus.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>BSWMD-Erstellung (Treiber- &amp; Stack-Lieferanten):</strong>\n<ul class=\"fig-list\"><li>Jedes BSW-Modul liefert eine formale ARXML-Beschreibung mit <code>BswModuleDescription</code> als Wurzelelement.\n</li><li>C-Funktionen werden über <code>implementedEntry</code> (Export) und <code>expectedEntry</code> (Import) modelliert, wodurch die Funktionsschnittstellen für den SchM- und RTE-Generator eindeutig deklariert werden.\n</li><li>Das Attribut <code>moduleId</code> ist optional (<code>[0..1]</code>), um standardisierte sowie herstellerspezifische Module und Bibliotheken abbilden zu können.\n</li></ul>\n</li><li><strong>Packaging, Variantenbildung und Per-Instance-Memory:</strong>\n<ul class=\"fig-list\"><li>Sämtliche Schnittstellenrollen an <code>BswModuleDescription</code> sowie <code>arTypedPerInstanceMemory</code> an <code>BswInternalBehavior</code> besitzen die Stereotypen <code>«atpVariation, atpSplitable»</code>. Dies erlaubt sowohl feingranulare Aufteilung über mehrere ARXML-Dateien als auch Variantenbindung zur Build- bzw. Post-Build-Zeit.\n</li><li><code>arTypedPerInstanceMemory</code> ermöglicht die AUTOSAR-konforme Typisierung von instanzspezifischem Speicher (PIM) direkt über <code>VariableDataPrototype</code> im internen Verhalten.\n</li></ul>\n</li><li><strong>Generierung des Basic Software Schedulers (SchM):</strong>\n<ul class=\"fig-list\"><li>Die Verknüpfung von <code>BswModuleDescription</code> mit <code>BswInternalBehavior</code> steuert die Generierung der <code>SchM_&lt;Bsw&gt;.h</code>-Header (z. B. Exclusive Areas via <code>SchM_Enter_&lt;Mod&gt;_&lt;Area&gt;()</code> und zyklische Main-Functions via <code>SchM_ActMainFunction_&lt;Mod&gt;()</code>).\n</li></ul>\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-7c1709db862b310e", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Diagrammtyp:</strong> AUTOSAR M2-Metamodell-Ausschnitt als UML-Klassendiagramm (Strukturdiagramm).\n</li><li><strong>Architektur-Kontext:</strong> Definition der Wurzelebene des BSW Module Description Templates (BSWMDT, AUTOSAR Classic Platform R4.0.3).\n</li><li><strong>Funktionaler Zweck:</strong> Formale Spezifikation der äußeren Hülle eines Basissoftware-Moduls (<code>BswModuleDescription</code>). Dient als maschinenlesbarer Vertrag (ARXML) für den BSW- und RTE/SchM-Generator zur Definition von Funktionsschnittstellen (APIs/Callbacks), Modulabhängigkeiten, Mode- und Trigger-Interaktionen sowie als Anker für das interne Verhalten (<code>BswInternalBehavior</code>).\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Entitäten und Klassenhierarchie</h5>\n<ul class=\"fig-list\"><li><strong><code>BswModuleDescription</code></strong>\n<ul class=\"fig-list\"><li><em>Vererbung / Stereotypen:</em> <code>ARElement</code>, <code>AtpBlueprint</code>, <code>AtpBlueprintable</code>, <code>AtpStructureElement</code>.\n</li><li><em>Attribute:</em> <code>+ moduleId: PositiveInteger [0..1]</code> (Normierte AUTOSAR-BSW-Modul-ID).\n</li><li><em>Rolle:</em> Top-Level-Beschreibungscontainer für ein einzelnes BSW-Modul (Treiber, Stack, Service).\n</li></ul>\n</li><li><strong><code>BswModuleEntry</code></strong>\n<ul class=\"fig-list\"><li><em>Vererbung / Stereotypen:</em> <code>ARElement</code>, <code>AtpBlueprint</code>, <code>AtpBlueprintable</code>.\n</li><li><em>Rolle:</em> Repräsentiert eine C-Funktionssignatur (C-API-Funktion, Main-Function oder Callback) auf C-Quellcodeebene.\n</li></ul>\n</li><li><strong><code>BswModuleDependency</code></strong>\n<ul class=\"fig-list\"><li><em>Vererbung / Stereotypen:</em> <code>Identifiable</code>.\n</li><li><em>Attribute:</em> <code>+ targetModuleId: PositiveInteger [0..1]</code> (Modul-ID des Zielmoduls).\n</li><li><em>Rolle:</em> Kapselt die vertraglichen Schnittstellenanforderungen an ein anderes BSW-Modul.\n</li></ul>\n</li><li><strong><code>ModeDeclarationGroupPrototype</code></strong>\n<ul class=\"fig-list\"><li><em>Vererbung / Stereotypen:</em> <code>AtpPrototype</code>.\n</li><li><em>Attribute:</em> <code>+ swCalibrationAccess: SwCalibrationAccessEnum [0..1]</code>.\n</li><li><em>Rolle:</em> Prototyp einer Modus-Deklarationsgruppe zur Festlegung von BSW-Zustandsmodi.\n</li></ul>\n</li><li><strong><code>Trigger</code></strong>\n<ul class=\"fig-list\"><li><em>Vererbung / Stereotypen:</em> <code>AtpStructureElement</code>, <code>Identifiable</code>.\n</li><li><em>Attribute:</em> <code>+ swImplPolicy: SwImplPolicyEnum [0..1]</code>.\n</li><li><em>Rolle:</em> Ereignisquelle für asynchrone Prozessaktivierungen ohne Parameterübertragung.\n</li></ul>\n</li><li><strong><code>BswModuleClientServerEntry</code></strong>\n<ul class=\"fig-list\"><li><em>Vererbung / Stereotypen:</em> <code>Referrable</code>.\n</li><li><em>Attribute:</em> <code>+ isReentrant: Boolean [0..1]</code>, <code>+ isSynchronous: Boolean [0..1]</code>.\n</li><li><em>Rolle:</em> Kapselt eine Client-Server-Schnittstelle innerhalb des BSW inklusive Synchronitäts- und Reentrancy-Eigenschaften.\n</li></ul>\n</li><li><strong><code>VariableDataPrototype</code></strong>\n<ul class=\"fig-list\"><li><em>Vererbung / Stereotypen:</em> <code>AutosarDataPrototype</code>.\n</li><li><em>Rolle:</em> Repräsentiert typisierte Datenprototypen für datenbasierte Schnittstellen sowie für per-Instance-Memory.\n</li></ul>\n</li><li><strong><code>BswInternalBehavior</code></strong>\n<ul class=\"fig-list\"><li><em>Vererbung / Stereotypen:</em> <code>InternalBehavior</code>.\n</li><li><em>Rolle:</em> Kapselung von BSW-Schedulable-Entities, Exclusive Areas, BSW-Events, Task-Mappings und instanzspezifischem Speicher.\n</li></ul>\n</li><li><strong><code>SwComponentDocumentation</code></strong>\n<ul class=\"fig-list\"><li><em>Archetyp:</em> Tag <code>A</code>.\n</li><li><em>Rolle:</em> Strukturierte technische Dokumentation des Moduls.\n</li></ul>\n</li></ul>\n<h5 class=\"fig-section-h5\">Beziehungen, Kardinalitäten und Stereotypen</h5>\n<div class=\"table-wrap\"><table class=\"fig-table\"><thead><tr><th>Quell-Element</th><th>Relation / Rolle</th><th>Ziel-Element</th><th>Kardinalität</th><th>Stereotypen</th><th>Semantik</th></tr></thead><tbody><tr><td><code>BswModuleDescription</code></td><td>Komposition <code>+bswModuleDocumentation</code></td><td><code>SwComponentDocumentation</code></td><td><code>0..1</code></td><td><code>«atpVariation, atpSplitable»</code></td><td>Dokumentationsanhang; varianten- und dateisplitfähig</td></tr><tr><td><code>BswModuleDescription</code></td><td>Assoziation <code>+implementedEntry</code></td><td><code>BswModuleEntry</code></td><td><code>0..*</code></td><td><code>«atpVariation, atpSplitable»</code></td><td>Vom Modul implementierte C-APIs; varianten- und dateisplitfähig</td></tr><tr><td><code>BswModuleDescription</code></td><td>Assoziation <code>+expectedEntry</code></td><td><code>BswModuleEntry</code></td><td><code>0..*</code></td><td><code>«atpVariation, atpSplitable»</code></td><td>Vom Modul erwartete C-APIs bzw. Callbacks; varianten- und dateisplitfähig</td></tr><tr><td><code>BswModuleDescription</code></td><td>Komposition <code>+bswModuleDependency</code></td><td><code>BswModuleDependency</code></td><td><code>0..*</code></td><td><code>«atpVariation, atpSplitable»</code></td><td>Deklarierte Abhängigkeit zu anderen BSW-Modulen</td></tr><tr><td><code>BswModuleDependency</code></td><td>Assoziation <code>+targetModuleRef</code></td><td><code>BswModuleDescription</code></td><td><code>0..1</code></td><td><code>«atpUriDef, atpVariation, atpSplitable»</code></td><td>Formale Referenz auf die Beschreibung des Zielmoduls via URI; varianten- und dateisplitfähig</td></tr><tr><td><code>BswModuleDescription</code></td><td>Komposition <code>+providedModeGroup</code></td><td><code>ModeDeclarationGroupPrototype</code></td><td><code>0..*</code></td><td><code>«atpVariation, atpSplitable»</code></td><td>Vom Modul verwaltete / bereitgestellte Zustandsmodi; varianten- und dateisplitfähig</td></tr><tr><td><code>BswModuleDescription</code></td><td>Komposition <code>+requiredModeGroup</code></td><td><code>ModeDeclarationGroupPrototype</code></td><td><code>0..*</code></td><td><code>«atpVariation, atpSplitable»</code></td><td>Vom Modul überwachte / benötigte Zustandsmodi; varianten- und dateisplitfähig</td></tr><tr><td><code>BswModuleDescription</code></td><td>Komposition <code>+releasedTrigger</code></td><td><code>Trigger</code></td><td><code>0..*</code></td><td><code>«atpVariation, atpSplitable»</code></td><td>Geworfene Trigger für RTE/BswM; varianten- und dateisplitfähig</td></tr><tr><td><code>BswModuleDescription</code></td><td>Komposition <code>+requiredTrigger</code></td><td><code>Trigger</code></td><td><code>0..*</code></td><td><code>«atpVariation, atpSplitable»</code></td><td>Konsumierte Trigger zur Aktivierung von Entities; varianten- und dateisplitfähig</td></tr><tr><td><code>BswModuleDescription</code></td><td>Assoziation <code>+providedClientServerEntry</code></td><td><code>BswModuleClientServerEntry</code></td><td><code>0..*</code></td><td><code>«atpVariation, atpSplitable»</code></td><td>Vom Modul angebotene Client-Server-Operationen; varianten- und dateisplitfähig</td></tr><tr><td><code>BswModuleDescription</code></td><td>Assoziation <code>+requiredClientServerEntry</code></td><td><code>BswModuleClientServerEntry</code></td><td><code>0..*</code></td><td><code>«atpVariation, atpSplitable»</code></td><td>Vom Modul angeforderte Client-Server-Operationen; varianten- und dateisplitfähig</td></tr><tr><td><code>BswModuleDescription</code></td><td>Assoziation <code>+providedData</code></td><td><code>VariableDataPrototype</code></td><td><code>0..*</code></td><td><code>«atpVariation, atpSplitable»</code></td><td>Vom Modul bereitgestellte Datenprototypen; varianten- und dateisplitfähig</td></tr><tr><td><code>BswModuleDescription</code></td><td>Assoziation <code>+requiredData</code></td><td><code>VariableDataPrototype</code></td><td><code>0..*</code></td><td><code>«atpVariation, atpSplitable»</code></td><td>Vom Modul benötigte Datenprototypen; varianten- und dateisplitfähig</td></tr><tr><td><code>BswModuleDescription</code></td><td>Komposition <code>+internalBehavior</code></td><td><code>BswInternalBehavior</code></td><td><code>0..*</code></td><td><code>«atpSplitable»</code></td><td>Internes Ausführungsverhalten (Split erlaubt Trennung über ARXML-Dateien)</td></tr><tr><td><code>BswInternalBehavior</code></td><td>Komposition <code>+arTypedPerInstanceMemory</code></td><td><code>VariableDataPrototype</code></td><td><code>0..*</code></td><td><code>«atpVariation, atpSplitable»</code></td><td>Instanzspezifischer Speicher für das interne Verhalten; varianten- und dateisplitfähig</td></tr></tbody></table></div>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Obgleich ein statisches Metamodell vorliegt, erzwingt die Struktur folgende dynamische Interaktionsmuster zur Laufzeit:</p>\n<ul class=\"fig-list\"><li><strong>Funktionsaufrufe und Schnittstellenimplementierung:</strong>\n<ul class=\"fig-list\"><li><code>implementedEntry</code> definiert die vom BSW-Modul konkret bereitgestellten C-Funktionseinstiegspunkte (APIs, Main-Functions).\n</li><li><code>expectedEntry</code> deklariert die vom Modul für den Betrieb vorausgesetzten externen C-Funktionen bzw. Callback-Signaturen.\n</li></ul>\n</li><li><strong>Client-Server-Interaktion:</strong>\n<ul class=\"fig-list\"><li><code>providedClientServerEntry</code> und <code>requiredClientServerEntry</code> steuern Client-Server-Aufrufe, parametriert über <code>isSynchronous</code> (blockierendes vs. asynchrones Verhalten) und <code>isReentrant</code> (Wiedereintrittsfähigkeit).\n</li></ul>\n</li><li><strong>Datenbasierte Kommunikation und interner Speicher:</strong>\n<ul class=\"fig-list\"><li><code>providedData</code> und <code>requiredData</code> definieren den Datenaustausch mit anderen BSW-Modulen oder Software-Components via <code>VariableDataPrototype</code>.\n</li><li><code>arTypedPerInstanceMemory</code> stellt typisierten Speicher pro Modulinstanz bereit, auf den die Entities des <code>BswInternalBehavior</code> zur Laufzeit zugreifen.\n</li></ul>\n</li><li><strong>Modulabhängigkeiten:</strong>\n<ul class=\"fig-list\"><li><code>BswModuleDependency</code> verknüpft das Modul über <code>targetModuleId</code> bzw. über eine URI-Referenz (<code>targetModuleRef</code>) mit der abhängigen <code>BswModuleDescription</code>.\n</li></ul>\n</li><li><strong>Mode-Switching &amp; State-Propagation:</strong>\n<ul class=\"fig-list\"><li>Moduswechsel werden über <code>providedModeGroup</code> an den BSW Mode Manager (<code>BswM</code>) propagiert oder über <code>requiredModeGroup</code> konsumiert.\n</li></ul>\n</li><li><strong>Asynchrones Triggering:</strong>\n<ul class=\"fig-list\"><li>Ereignisse werden über <code>releasedTrigger</code> abgesetzt und lösen über <code>requiredTrigger</code> verknüpfte Abarbeitungsfolgen im SchM/OS aus.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>BSWMD-Erstellung (Treiber- &amp; Stack-Lieferanten):</strong>\n<ul class=\"fig-list\"><li>Jedes BSW-Modul liefert eine formale ARXML-Beschreibung mit <code>BswModuleDescription</code> als Wurzelelement.\n</li><li>C-Funktionen werden über <code>implementedEntry</code> (Export) und <code>expectedEntry</code> (Import) modelliert, wodurch die Funktionsschnittstellen für den SchM- und RTE-Generator eindeutig deklariert werden.\n</li><li>Das Attribut <code>moduleId</code> ist optional (<code>[0..1]</code>), um standardisierte sowie herstellerspezifische Module und Bibliotheken abbilden zu können.\n</li></ul>\n</li><li><strong>Packaging, Variantenbildung und Splitfähigkeit:</strong>\n<ul class=\"fig-list\"><li>Sämtliche Schnittstellenrollen an <code>BswModuleDescription</code>, <code>arTypedPerInstanceMemory</code> an <code>BswInternalBehavior</code> sowie <code>targetModuleRef</code> an <code>BswModuleDependency</code> besitzen den Stereotyp <code>«atpSplitable»</code>. Dies erlaubt eine vollständige dateiübergreifende Aufteilung auch von externen Modulverweisen (<code>«atpUriDef, atpVariation, atpSplitable»</code>).\n</li><li><code>«atpVariation»</code> ermöglicht durchgängige Variantenbildung über System-Constants.\n</li></ul>\n</li><li><strong>Generierung des Basic Software Schedulers (SchM):</strong>\n<ul class=\"fig-list\"><li>Die Verknüpfung von <code>BswModuleDescription</code> mit <code>BswInternalBehavior</code> steuert die Generierung der <code>SchM_&lt;Bsw&gt;.h</code>-Header (z. B. Exclusive Areas via <code>SchM_Enter_&lt;Mod&gt;_&lt;Area&gt;()</code> und zyklische Main-Functions via <code>SchM_ActMainFunction_&lt;Mod&gt;()</code>).\n</li></ul>\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-cb916ca9f81890ee", "releases": ["R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Diagrammtyp:</strong> AUTOSAR M2-Metamodell-Ausschnitt als UML-Klassendiagramm (Strukturdiagramm).\n</li><li><strong>Architektur-Kontext:</strong> Definition der Wurzelebene des BSW Module Description Templates (BSWMDT, AUTOSAR Classic Platform R4.0.3).\n</li><li><strong>Funktionaler Zweck:</strong> Formale Spezifikation der äußeren Hülle eines Basissoftware-Moduls (<code>BswModuleDescription</code>). Dient als maschinenlesbarer Vertrag (ARXML) für den BSW- und RTE/SchM-Generator zur Definition von Funktionsschnittstellen (APIs/Callbacks), Modulabhängigkeiten, Mode- und Trigger-Interaktionen sowie als Anker für das interne Verhalten (<code>BswInternalBehavior</code>).\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Entitäten und Klassenhierarchie</h5>\n<ul class=\"fig-list\"><li><strong><code>BswModuleDescription</code></strong>\n<ul class=\"fig-list\"><li><em>Vererbung / Stereotypen:</em> <code>ARElement</code>, <code>AtpBlueprint</code>, <code>AtpBlueprintable</code>, <code>AtpStructureElement</code>.\n</li><li><em>Attribute:</em> <code>+ moduleId: PositiveInteger [0..1]</code> (Normierte AUTOSAR-BSW-Modul-ID).\n</li><li><em>Rolle:</em> Top-Level-Beschreibungscontainer für ein einzelnes BSW-Modul (Treiber, Stack, Service).\n</li></ul>\n</li><li><strong><code>BswModuleEntry</code></strong>\n<ul class=\"fig-list\"><li><em>Vererbung / Stereotypen:</em> <code>ARElement</code>, <code>AtpBlueprint</code>, <code>AtpBlueprintable</code>.\n</li><li><em>Rolle:</em> Repräsentiert eine C-Funktionssignatur (C-API-Funktion, Main-Function oder Callback) auf C-Quellcodeebene.\n</li></ul>\n</li><li><strong><code>BswModuleDependency</code></strong>\n<ul class=\"fig-list\"><li><em>Vererbung / Stereotypen:</em> <code>Identifiable</code>.\n</li><li><em>Attribute:</em> <code>+ targetModuleId: PositiveInteger [0..1]</code> (Modul-ID des Zielmoduls).\n</li><li><em>Rolle:</em> Kapselt die vertraglichen Schnittstellenanforderungen an ein anderes BSW-Modul.\n</li></ul>\n</li><li><strong><code>ModeDeclarationGroupPrototype</code></strong>\n<ul class=\"fig-list\"><li><em>Vererbung / Stereotypen:</em> <code>AtpPrototype</code>.\n</li><li><em>Attribute:</em> <code>+ swCalibrationAccess: SwCalibrationAccessEnum [0..1]</code>.\n</li><li><em>Rolle:</em> Prototyp einer Modus-Deklarationsgruppe zur Festlegung von BSW-Zustandsmodi.\n</li></ul>\n</li><li><strong><code>Trigger</code></strong>\n<ul class=\"fig-list\"><li><em>Vererbung / Stereotypen:</em> <code>AtpStructureElement</code>, <code>Identifiable</code>.\n</li><li><em>Attribute:</em> <code>+ swImplPolicy: SwImplPolicyEnum [0..1]</code>.\n</li><li><em>Rolle:</em> Ereignisquelle für asynchrone Prozessaktivierungen ohne Parameterübertragung.\n</li></ul>\n</li><li><strong><code>BswModuleClientServerEntry</code></strong>\n<ul class=\"fig-list\"><li><em>Vererbung / Stereotypen:</em> <code>Referrable</code>.\n</li><li><em>Attribute:</em> <code>+ isReentrant: Boolean [0..1]</code>, <code>+ isSynchronous: Boolean [0..1]</code>.\n</li><li><em>Rolle:</em> Kapselt eine Client-Server-Schnittstelle innerhalb des BSW inklusive Synchronitäts- und Reentrancy-Eigenschaften.\n</li></ul>\n</li><li><strong><code>VariableDataPrototype</code></strong>\n<ul class=\"fig-list\"><li><em>Vererbung / Stereotypen:</em> <code>AutosarDataPrototype</code>.\n</li><li><em>Rolle:</em> Repräsentiert typisierte Datenprototypen für datenbasierte Schnittstellen sowie für per-Instance-Memory.\n</li></ul>\n</li><li><strong><code>BswInternalBehavior</code></strong>\n<ul class=\"fig-list\"><li><em>Vererbung / Stereotypen:</em> <code>InternalBehavior</code>.\n</li><li><em>Rolle:</em> Kapselung von BSW-Schedulable-Entities, Exclusive Areas, BSW-Events, Task-Mappings und instanzspezifischem Speicher.\n</li></ul>\n</li><li><strong><code>SwComponentDocumentation</code></strong>\n<ul class=\"fig-list\"><li><em>Archetyp:</em> Tag <code>A</code>.\n</li><li><em>Rolle:</em> Strukturierte technische Dokumentation des Moduls.\n</li></ul>\n</li></ul>\n<h5 class=\"fig-section-h5\">Beziehungen, Kardinalitäten und Stereotypen</h5>\n<div class=\"table-wrap\"><table class=\"fig-table\"><thead><tr><th>Quell-Element</th><th>Relation / Rolle</th><th>Ziel-Element</th><th>Kardinalität</th><th>Stereotypen</th><th>Semantik</th></tr></thead><tbody><tr><td><code>BswModuleDescription</code></td><td>Komposition <code>+bswModuleDocumentation</code></td><td><code>SwComponentDocumentation</code></td><td><code>0..1</code></td><td><code>«atpVariation, atpSplitable»</code></td><td>Dokumentationsanhang; varianten- und dateisplitfähig</td></tr><tr><td><code>BswModuleDescription</code></td><td>Assoziation <code>+implementedEntry</code></td><td><code>BswModuleEntry</code></td><td><code>0..*</code></td><td><code>«atpVariation, atpSplitable»</code></td><td>Vom Modul implementierte C-APIs; varianten- und dateisplitfähig</td></tr><tr><td><code>BswModuleDescription</code></td><td>Assoziation <code>+expectedEntry</code></td><td><code>BswModuleEntry</code></td><td><code>0..*</code></td><td><code>«atpVariation, atpSplitable»</code></td><td>Vom Modul erwartete C-APIs bzw. Callbacks; varianten- und dateisplitfähig</td></tr><tr><td><code>BswModuleDescription</code></td><td>Komposition <code>+bswModuleDependency</code></td><td><code>BswModuleDependency</code></td><td><code>0..*</code></td><td><code>«atpVariation, atpSplitable»</code></td><td>Deklarierte Abhängigkeit zu anderen BSW-Modulen</td></tr><tr><td><code>BswModuleDependency</code></td><td>Assoziation <code>+targetModuleRef</code></td><td><code>BswModuleDescription</code></td><td><code>0..1</code></td><td><code>«atpUriDef, atpVariation, atpSplitable»</code></td><td>Formale Referenz auf die Beschreibung des Zielmoduls via URI; varianten- und dateisplitfähig</td></tr><tr><td><code>BswModuleDescription</code></td><td>Komposition <code>+providedModeGroup</code></td><td><code>ModeDeclarationGroupPrototype</code></td><td><code>0..*</code></td><td><code>«atpVariation, atpSplitable»</code></td><td>Vom Modul verwaltete / bereitgestellte Zustandsmodi; varianten- und dateisplitfähig</td></tr><tr><td><code>BswModuleDescription</code></td><td>Komposition <code>+requiredModeGroup</code></td><td><code>ModeDeclarationGroupPrototype</code></td><td><code>0..*</code></td><td><code>«atpVariation, atpSplitable»</code></td><td>Vom Modul überwachte / benötigte Zustandsmodi; varianten- und dateisplitfähig</td></tr><tr><td><code>BswModuleDescription</code></td><td>Komposition <code>+releasedTrigger</code></td><td><code>Trigger</code></td><td><code>0..*</code></td><td><code>«atpVariation, atpSplitable»</code></td><td>Geworfene Trigger für RTE/BswM; varianten- und dateisplitfähig</td></tr><tr><td><code>BswModuleDescription</code></td><td>Komposition <code>+requiredTrigger</code></td><td><code>Trigger</code></td><td><code>0..*</code></td><td><code>«atpVariation, atpSplitable»</code></td><td>Konsumierte Trigger zur Aktivierung von Entities; varianten- und dateisplitfähig</td></tr><tr><td><code>BswModuleDescription</code></td><td>Assoziation <code>+providedClientServerEntry</code></td><td><code>BswModuleClientServerEntry</code></td><td><code>0..*</code></td><td><code>«atpVariation, atpSplitable»</code></td><td>Vom Modul angebotene Client-Server-Operationen; varianten- und dateisplitfähig</td></tr><tr><td><code>BswModuleDescription</code></td><td>Assoziation <code>+requiredClientServerEntry</code></td><td><code>BswModuleClientServerEntry</code></td><td><code>0..*</code></td><td><code>«atpVariation, atpSplitable»</code></td><td>Vom Modul angeforderte Client-Server-Operationen; varianten- und dateisplitfähig</td></tr><tr><td><code>BswModuleDescription</code></td><td>Assoziation <code>+providedData</code></td><td><code>VariableDataPrototype</code></td><td><code>0..*</code></td><td><code>«atpVariation, atpSplitable»</code></td><td>Vom Modul bereitgestellte Datenprototypen; varianten- und dateisplitfähig</td></tr><tr><td><code>BswModuleDescription</code></td><td>Assoziation <code>+requiredData</code></td><td><code>VariableDataPrototype</code></td><td><code>0..*</code></td><td><code>«atpVariation, atpSplitable»</code></td><td>Vom Modul benötigte Datenprototypen; varianten- und dateisplitfähig</td></tr><tr><td><code>BswModuleDescription</code></td><td>Komposition <code>+internalBehavior</code></td><td><code>BswInternalBehavior</code></td><td><code>0..*</code></td><td><code>«atpSplitable»</code></td><td>Internes Ausführungsverhalten (Split erlaubt Trennung über ARXML-Dateien)</td></tr><tr><td><code>BswInternalBehavior</code></td><td>Komposition <code>+arTypedPerInstanceMemory</code></td><td><code>VariableDataPrototype</code></td><td><code>0..*</code></td><td><code>«atpVariation, atpSplitable»</code></td><td>Instanzspezifischer Speicher für das interne Verhalten; varianten- und dateisplitfähig</td></tr></tbody></table></div>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Obgleich ein statisches Metamodell vorliegt, erzwingt die Struktur folgende dynamische Interaktionsmuster zur Laufzeit:</p>\n<ul class=\"fig-list\"><li><strong>Funktionsaufrufe und Schnittstellenimplementierung:</strong>\n<ul class=\"fig-list\"><li><code>implementedEntry</code> definiert die vom BSW-Modul konkret bereitgestellten C-Funktionseinstiegspunkte (APIs, Main-Functions).\n</li><li><code>expectedEntry</code> deklariert die vom Modul für den Betrieb vorausgesetzten externen C-Funktionen bzw. Callback-Signaturen.\n</li></ul>\n</li><li><strong>Client-Server-Interaktion:</strong>\n<ul class=\"fig-list\"><li><code>providedClientServerEntry</code> und <code>requiredClientServerEntry</code> steuern Client-Server-Aufrufe, parametriert über <code>isSynchronous</code> (blockierendes vs. asynchrones Verhalten) und <code>isReentrant</code> (Wiedereintrittsfähigkeit).\n</li></ul>\n</li><li><strong>Datenbasierte Kommunikation und interner Speicher:</strong>\n<ul class=\"fig-list\"><li><code>providedData</code> und <code>requiredData</code> definieren den Datenaustausch mit anderen BSW-Modulen oder Software-Components via <code>VariableDataPrototype</code>.\n</li><li><code>arTypedPerInstanceMemory</code> stellt typisierten Speicher pro Modulinstanz bereit, auf den die Entities des <code>BswInternalBehavior</code> zur Laufzeit zugreifen.\n</li></ul>\n</li><li><strong>Modulabhängigkeiten:</strong>\n<ul class=\"fig-list\"><li><code>BswModuleDependency</code> verknüpft das Modul über <code>targetModuleId</code> bzw. über eine URI-Referenz (<code>targetModuleRef</code>) mit der abhängigen <code>BswModuleDescription</code>.\n</li></ul>\n</li><li><strong>Mode-Switching &amp; State-Propagation:</strong>\n<ul class=\"fig-list\"><li>Moduswechsel werden über <code>providedModeGroup</code> an den BSW Mode Manager (<code>BswM</code>) propagiert oder über <code>requiredModeGroup</code> konsumiert.\n</li></ul>\n</li><li><strong>Asynchrones Triggering:</strong>\n<ul class=\"fig-list\"><li>Ereignisse werden über <code>releasedTrigger</code> abgesetzt und lösen über <code>requiredTrigger</code> verknüpfte Abarbeitungsfolgen im SchM/OS aus.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>BSWMD-Erstellung (Treiber- &amp; Stack-Lieferanten):</strong>\n<ul class=\"fig-list\"><li>Jedes BSW-Modul liefert eine formale ARXML-Beschreibung mit <code>BswModuleDescription</code> als Wurzelelement.\n</li><li>C-Funktionen werden über <code>implementedEntry</code> (Export) und <code>expectedEntry</code> (Import) modelliert, wodurch die Funktionsschnittstellen für den SchM- und RTE-Generator eindeutig deklariert werden.\n</li><li>Das Attribut <code>moduleId</code> ist optional (<code>[0..1]</code>), um standardisierte sowie herstellerspezifische Module und Bibliotheken abbilden zu können.\n</li></ul>\n</li><li><strong>Packaging, Variantenbildung und Splitfähigkeit:</strong>\n<ul class=\"fig-list\"><li>Sämtliche Schnittstellenrollen an <code>BswModuleDescription</code>, <code>arTypedPerInstanceMemory</code> an <code>BswInternalBehavior</code> sowie <code>targetModuleRef</code> an <code>BswModuleDependency</code> besitzen den Stereotyp <code>«atpSplitable»</code>. Dies erlaubt eine vollständige dateiübergreifende Aufteilung auch von externen Modulverweisen (<code>«atpUriDef, atpVariation, atpSplitable»</code>).\n</li><li><code>«atpVariation»</code> ermöglicht durchgängige Variantenbildung über System-Constants.\n</li></ul>\n</li><li><strong>Generierung des Basic Software Schedulers (SchM):</strong>\n<ul class=\"fig-list\"><li>Die Verknüpfung von <code>BswModuleDescription</code> mit <code>BswInternalBehavior</code> steuert die Generierung der <code>SchM_&lt;Bsw&gt;.h</code>-Header (z. B. Exclusive Areas via <code>SchM_Enter_&lt;Mod&gt;_&lt;Area&gt;()</code> und zyklische Main-Functions via <code>SchM_ActMainFunction_&lt;Mod&gt;()</code>).\n</li></ul>\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-7c346486e3c18ffb", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Diagrammtyp:</strong> AUTOSAR M2-Metamodell-Ausschnitt als UML-Klassendiagramm (Strukturdiagramm).\n</li><li><strong>Architektur-Kontext:</strong> Definition der Wurzelebene des BSW Module Description Templates (BSWMDT, AUTOSAR Classic Platform R4.0.3).\n</li><li><strong>Funktionaler Zweck:</strong> Formale Spezifikation der äußeren Hülle eines Basissoftware-Moduls (<code>BswModuleDescription</code>). Dient als maschinenlesbarer Vertrag (ARXML) für den BSW- und RTE/SchM-Generator zur Definition von Funktionsschnittstellen (APIs/Callbacks), Modulabhängigkeiten, Mode- und Trigger-Interaktionen sowie als Anker für das interne Verhalten (<code>BswInternalBehavior</code>).\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Entitäten und Klassenhierarchie</h5>\n<ul class=\"fig-list\"><li><strong><code>BswModuleDescription</code></strong>\n<ul class=\"fig-list\"><li><em>Vererbung / Stereotypen:</em> <code>ARElement</code>, <code>AtpBlueprint</code>, <code>AtpBlueprintable</code>, <code>AtpStructureElement</code>.\n</li><li><em>Attribute:</em> <code>+ moduleId: PositiveInteger [0..1]</code> (Normierte AUTOSAR-BSW-Modul-ID).\n</li><li><em>Rolle:</em> Top-Level-Beschreibungscontainer für ein einzelnes BSW-Modul (Treiber, Stack, Service).\n</li></ul>\n</li><li><strong><code>BswModuleEntry</code></strong>\n<ul class=\"fig-list\"><li><em>Vererbung / Stereotypen:</em> <code>ARElement</code>, <code>AtpBlueprint</code>, <code>AtpBlueprintable</code>.\n</li><li><em>Rolle:</em> Repräsentiert eine C-Funktionssignatur (C-API-Funktion, Main-Function oder Callback) auf C-Quellcodeebene.\n</li></ul>\n</li><li><strong><code>BswModuleDependency</code></strong>\n<ul class=\"fig-list\"><li><em>Vererbung / Stereotypen:</em> <code>Identifiable</code>.\n</li><li><em>Attribute:</em> <code>+ targetModuleId: PositiveInteger [0..1]</code> (Modul-ID des Zielmoduls).\n</li><li><em>Rolle:</em> Kapselt die vertraglichen Schnittstellenanforderungen an ein anderes BSW-Modul.\n</li></ul>\n</li><li><strong><code>ModeDeclarationGroupPrototype</code></strong>\n<ul class=\"fig-list\"><li><em>Vererbung / Stereotypen:</em> <code>AtpPrototype</code>.\n</li><li><em>Attribute:</em> <code>+ swCalibrationAccess: SwCalibrationAccessEnum [0..1]</code>.\n</li><li><em>Rolle:</em> Prototyp einer Modus-Deklarationsgruppe zur Festlegung von BSW-Zustandsmodi.\n</li></ul>\n</li><li><strong><code>Trigger</code></strong>\n<ul class=\"fig-list\"><li><em>Vererbung / Stereotypen:</em> <code>AtpStructureElement</code>, <code>Identifiable</code>.\n</li><li><em>Attribute:</em> <code>+ swImplPolicy: SwImplPolicyEnum [0..1]</code>.\n</li><li><em>Rolle:</em> Ereignisquelle für asynchrone Prozessaktivierungen ohne Parameterübertragung.\n</li></ul>\n</li><li><strong><code>BswModuleClientServerEntry</code></strong>\n<ul class=\"fig-list\"><li><em>Vererbung / Stereotypen:</em> <code>Referrable</code>.\n</li><li><em>Attribute:</em> <code>+ isReentrant: Boolean [0..1]</code>, <code>+ isSynchronous: Boolean [0..1]</code>.\n</li><li><em>Rolle:</em> Kapselt eine Client-Server-Schnittstelle innerhalb des BSW inklusive Synchronitäts- und Reentrancy-Eigenschaften.\n</li></ul>\n</li><li><strong><code>VariableDataPrototype</code></strong>\n<ul class=\"fig-list\"><li><em>Vererbung / Stereotypen:</em> <code>AutosarDataPrototype</code>.\n</li><li><em>Rolle:</em> Repräsentiert typisierte Datenprototypen für datenbasierte Schnittstellen sowie für per-Instance-Memory.\n</li></ul>\n</li><li><strong><code>BswInternalBehavior</code></strong>\n<ul class=\"fig-list\"><li><em>Vererbung / Stereotypen:</em> <code>InternalBehavior</code>.\n</li><li><em>Rolle:</em> Kapselung von BSW-Schedulable-Entities, Exclusive Areas, BSW-Events, Task-Mappings und instanzspezifischem Speicher.\n</li></ul>\n</li><li><strong><code>SwComponentDocumentation</code></strong>\n<ul class=\"fig-list\"><li><em>Rolle:</em> Strukturierte technische Dokumentation des Moduls.\n</li></ul>\n</li></ul>\n<h5 class=\"fig-section-h5\">Beziehungen, Kardinalitäten und Stereotypen</h5>\n<div class=\"table-wrap\"><table class=\"fig-table\"><thead><tr><th>Quell-Element</th><th>Relation / Rolle</th><th>Ziel-Element</th><th>Kardinalität</th><th>Stereotypen</th><th>Semantik</th></tr></thead><tbody><tr><td><code>BswModuleDescription</code></td><td>Komposition <code>+bswModuleDocumentation</code></td><td><code>SwComponentDocumentation</code></td><td><code>0..1</code></td><td><code>«atpVariation, atpSplitable»</code></td><td>Dokumentationsanhang; varianten- und dateisplitfähig</td></tr><tr><td><code>BswModuleDescription</code></td><td>Assoziation <code>+implementedEntry</code></td><td><code>BswModuleEntry</code></td><td><code>0..*</code></td><td><code>«atpVariation, atpSplitable»</code></td><td>Vom Modul implementierte C-APIs; varianten- und dateisplitfähig</td></tr><tr><td><code>BswModuleDescription</code></td><td>Assoziation <code>+expectedEntry</code></td><td><code>BswModuleEntry</code></td><td><code>0..*</code></td><td><code>«atpVariation, atpSplitable»</code></td><td>Vom Modul erwartete C-APIs bzw. Callbacks; varianten- und dateisplitfähig</td></tr><tr><td><code>BswModuleDescription</code></td><td>Komposition <code>+bswModuleDependency</code></td><td><code>BswModuleDependency</code></td><td><code>0..*</code></td><td><code>«atpVariation, atpSplitable»</code></td><td>Deklarierte Abhängigkeit zu anderen BSW-Modulen</td></tr><tr><td><code>BswModuleDependency</code></td><td>Assoziation <code>+targetModuleRef</code></td><td><code>BswModuleDescription</code></td><td><code>0..1</code></td><td><code>«atpUriDef, atpVariation, atpSplitable»</code></td><td>Formale Referenz auf die Beschreibung des Zielmoduls via URI; varianten- und dateisplitfähig</td></tr><tr><td><code>BswModuleDescription</code></td><td>Komposition <code>+providedModeGroup</code></td><td><code>ModeDeclarationGroupPrototype</code></td><td><code>0..* {subsets atpFeature}</code></td><td><code>«atpVariation, atpSplitable»</code></td><td>Vom Modul verwaltete / bereitgestellte Zustandsmodi; varianten- und dateisplitfähig</td></tr><tr><td><code>BswModuleDescription</code></td><td>Komposition <code>+requiredModeGroup</code></td><td><code>ModeDeclarationGroupPrototype</code></td><td><code>0..* {subsets atpFeature}</code></td><td><code>«atpVariation, atpSplitable»</code></td><td>Vom Modul überwachte / benötigte Zustandsmodi; varianten- und dateisplitfähig</td></tr><tr><td><code>BswModuleDescription</code></td><td>Komposition <code>+releasedTrigger</code></td><td><code>Trigger</code></td><td><code>0..*</code></td><td><code>«atpVariation, atpSplitable»</code></td><td>Geworfene Trigger für RTE/BswM; varianten- und dateisplitfähig</td></tr><tr><td><code>BswModuleDescription</code></td><td>Komposition <code>+requiredTrigger</code></td><td><code>Trigger</code></td><td><code>0..*</code></td><td><code>«atpVariation, atpSplitable»</code></td><td>Konsumierte Trigger zur Aktivierung von Entities; varianten- und dateisplitfähig</td></tr><tr><td><code>BswModuleDescription</code></td><td>Assoziation <code>+providedClientServerEntry</code></td><td><code>BswModuleClientServerEntry</code></td><td><code>0..*</code></td><td><code>«atpVariation, atpSplitable»</code></td><td>Vom Modul angebotene Client-Server-Operationen; varianten- und dateisplitfähig</td></tr><tr><td><code>BswModuleDescription</code></td><td>Assoziation <code>+requiredClientServerEntry</code></td><td><code>BswModuleClientServerEntry</code></td><td><code>0..*</code></td><td><code>«atpVariation, atpSplitable»</code></td><td>Vom Modul angeforderte Client-Server-Operationen; varianten- und dateisplitfähig</td></tr><tr><td><code>BswModuleDescription</code></td><td>Assoziation <code>+providedData</code></td><td><code>VariableDataPrototype</code></td><td><code>0..*</code></td><td><code>«atpVariation, atpSplitable»</code></td><td>Vom Modul bereitgestellte Datenprototypen; varianten- und dateisplitfähig</td></tr><tr><td><code>BswModuleDescription</code></td><td>Assoziation <code>+requiredData</code></td><td><code>VariableDataPrototype</code></td><td><code>0..*</code></td><td><code>«atpVariation, atpSplitable»</code></td><td>Vom Modul benötigte Datenprototypen; varianten- und dateisplitfähig</td></tr><tr><td><code>BswModuleDescription</code></td><td>Komposition <code>+internalBehavior</code></td><td><code>BswInternalBehavior</code></td><td><code>0..*</code></td><td><code>«atpSplitable»</code></td><td>Internes Ausführungsverhalten (Split erlaubt Trennung über ARXML-Dateien)</td></tr><tr><td><code>BswInternalBehavior</code></td><td>Komposition <code>+arTypedPerInstanceMemory</code></td><td><code>VariableDataPrototype</code></td><td><code>0..*</code></td><td><code>«atpVariation, atpSplitable»</code></td><td>Instanzspezifischer Speicher für das interne Verhalten; varianten- und dateisplitfähig</td></tr></tbody></table></div>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Obgleich ein statisches Metamodell vorliegt, erzwingt die Struktur folgende dynamische Interaktionsmuster zur Laufzeit:</p>\n<ul class=\"fig-list\"><li><strong>Funktionsaufrufe und Schnittstellenimplementierung:</strong>\n<ul class=\"fig-list\"><li><code>implementedEntry</code> definiert die vom BSW-Modul konkret bereitgestellten C-Funktionseinstiegspunkte (APIs, Main-Functions).\n</li><li><code>expectedEntry</code> deklariert die vom Modul für den Betrieb vorausgesetzten externen C-Funktionen bzw. Callback-Signaturen.\n</li></ul>\n</li><li><strong>Client-Server-Interaktion:</strong>\n<ul class=\"fig-list\"><li><code>providedClientServerEntry</code> und <code>requiredClientServerEntry</code> steuern Client-Server-Aufrufe, parametriert über <code>isSynchronous</code> (blockierendes vs. asynchrones Verhalten) und <code>isReentrant</code> (Wiedereintrittsfähigkeit).\n</li></ul>\n</li><li><strong>Datenbasierte Kommunikation und interner Speicher:</strong>\n<ul class=\"fig-list\"><li><code>providedData</code> und <code>requiredData</code> definieren den Datenaustausch mit anderen BSW-Modulen oder Software-Components via <code>VariableDataPrototype</code>.\n</li><li><code>arTypedPerInstanceMemory</code> stellt typisierten Speicher pro Modulinstanz bereit, auf den die Entities des <code>BswInternalBehavior</code> zur Laufzeit zugreifen.\n</li></ul>\n</li><li><strong>Modulabhängigkeiten:</strong>\n<ul class=\"fig-list\"><li><code>BswModuleDependency</code> verknüpft das Modul über <code>targetModuleId</code> bzw. über eine URI-Referenz (<code>targetModuleRef</code>) mit der abhängigen <code>BswModuleDescription</code>.\n</li></ul>\n</li><li><strong>Mode-Switching &amp; State-Propagation:</strong>\n<ul class=\"fig-list\"><li>Moduswechsel werden über <code>providedModeGroup</code> an den BSW Mode Manager (<code>BswM</code>) propagiert oder über <code>requiredModeGroup</code> konsumiert.\n</li></ul>\n</li><li><strong>Asynchrones Triggering:</strong>\n<ul class=\"fig-list\"><li>Ereignisse werden über <code>releasedTrigger</code> abgesetzt und lösen über <code>requiredTrigger</code> verknüpfte Abarbeitungsfolgen im SchM/OS aus.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>BSWMD-Erstellung (Treiber- &amp; Stack-Lieferanten):</strong>\n<ul class=\"fig-list\"><li>Jedes BSW-Modul liefert eine formale ARXML-Beschreibung mit <code>BswModuleDescription</code> als Wurzelelement.\n</li><li>C-Funktionen werden über <code>implementedEntry</code> (Export) und <code>expectedEntry</code> (Import) modelliert, wodurch die Funktionsschnittstellen für den SchM- und RTE-Generator eindeutig deklariert werden.\n</li><li>Das Attribut <code>moduleId</code> ist optional (<code>[0..1]</code>), um standardisierte sowie herstellerspezifische Module und Bibliotheken abbilden zu können.\n</li></ul>\n</li><li><strong>Packaging, Variantenbildung und Splitfähigkeit:</strong>\n<ul class=\"fig-list\"><li>Sämtliche Schnittstellenrollen an <code>BswModuleDescription</code>, <code>arTypedPerInstanceMemory</code> an <code>BswInternalBehavior</code> sowie <code>targetModuleRef</code> an <code>BswModuleDependency</code> besitzen den Stereotyp <code>«atpSplitable»</code>. Dies erlaubt eine vollständige dateiübergreifende Aufteilung auch von externen Modulverweisen (<code>«atpUriDef, atpVariation, atpSplitable»</code>).\n</li><li><code>«atpVariation»</code> ermöglicht durchgängige Variantenbildung über System-Constants.\n</li></ul>\n</li><li><strong>Generierung des Basic Software Schedulers (SchM):</strong>\n<ul class=\"fig-list\"><li>Die Verknüpfung von <code>BswModuleDescription</code> mit <code>BswInternalBehavior</code> steuert die Generierung der <code>SchM_&lt;Bsw&gt;.h</code>-Header (z. B. Exclusive Areas via <code>SchM_Enter_&lt;Mod&gt;_&lt;Area&gt;()</code> und zyklische Main-Functions via <code>SchM_ActMainFunction_&lt;Mod&gt;()</code>).\n</li></ul>\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-8259e072517b0262", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\"><li><strong>Diagrammtyp:</strong> AUTOSAR M2-Metamodell-Ausschnitt als UML-Klassendiagramm (Strukturdiagramm).\n</li><li><strong>Architektur-Kontext:</strong> Definition der Wurzelebene des BSW Module Description Templates (BSWMDT, AUTOSAR Classic Platform R4.0.3).\n</li><li><strong>Funktionaler Zweck:</strong> Formale Spezifikation der äußeren Hülle eines Basissoftware-Moduls (<code>BswModuleDescription</code>). Dient als maschinenlesbarer Vertrag (ARXML) für den BSW- und RTE/SchM-Generator zur Definition von Funktionsschnittstellen (APIs/Callbacks), Modulabhängigkeiten, Mode- und Trigger-Interaktionen sowie als Anker für das interne Verhalten (<code>BswInternalBehavior</code>).\n</li></ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<h5 class=\"fig-section-h5\">Entitäten und Klassenhierarchie</h5>\n<ul class=\"fig-list\"><li><strong><code>BswModuleDescription</code></strong>\n<ul class=\"fig-list\"><li><em>Vererbung / Stereotypen:</em> <code>ARElement</code>, <code>AtpBlueprint</code>, <code>AtpBlueprintable</code>, <code>AtpStructureElement</code>.\n</li><li><em>Attribute:</em> <code>+ moduleId: PositiveInteger [0..1]</code> (Normierte AUTOSAR-BSW-Modul-ID).\n</li><li><em>Rolle:</em> Top-Level-Beschreibungscontainer für ein einzelnes BSW-Modul (Treiber, Stack, Service).\n</li></ul>\n</li><li><strong><code>BswModuleEntry</code></strong>\n<ul class=\"fig-list\"><li><em>Vererbung / Stereotypen:</em> <code>ARElement</code>, <code>AtpBlueprint</code>, <code>AtpBlueprintable</code>.\n</li><li><em>Rolle:</em> Repräsentiert eine C-Funktionssignatur (C-API-Funktion, Main-Function oder Callback) auf C-Quellcodeebene.\n</li></ul>\n</li><li><strong><code>BswModuleDependency</code></strong>\n<ul class=\"fig-list\"><li><em>Vererbung / Stereotypen:</em> <code>Identifiable</code>.\n</li><li><em>Attribute:</em> <code>+ targetModuleId: PositiveInteger [0..1]</code> (Modul-ID des Zielmoduls).\n</li><li><em>Rolle:</em> Kapselt die vertraglichen Schnittstellenanforderungen an ein anderes BSW-Modul.\n</li></ul>\n</li><li><strong><code>ModeDeclarationGroupPrototype</code></strong>\n<ul class=\"fig-list\"><li><em>Vererbung / Stereotypen:</em> <code>AtpPrototype</code>.\n</li><li><em>Attribute:</em> <code>+ swCalibrationAccess: SwCalibrationAccessEnum [0..1]</code>.\n</li><li><em>Rolle:</em> Prototyp einer Modus-Deklarationsgruppe zur Festlegung von BSW-Zustandsmodi.\n</li></ul>\n</li><li><strong><code>Trigger</code></strong>\n<ul class=\"fig-list\"><li><em>Vererbung / Stereotypen:</em> <code>AtpStructureElement</code>, <code>Identifiable</code>.\n</li><li><em>Attribute:</em> <code>+ swImplPolicy: SwImplPolicyEnum [0..1]</code>.\n</li><li><em>Rolle:</em> Ereignisquelle für asynchrone Prozessaktivierungen ohne Parameterübertragung.\n</li></ul>\n</li><li><strong><code>BswModuleClientServerEntry</code></strong>\n<ul class=\"fig-list\"><li><em>Vererbung / Stereotypen:</em> <code>Referrable</code>.\n</li><li><em>Attribute:</em> <code>+ isReentrant: Boolean [0..1]</code>, <code>+ isSynchronous: Boolean [0..1]</code>.\n</li><li><em>Rolle:</em> Kapselt eine Client-Server-Schnittstelle innerhalb des BSW inklusive Synchronitäts- und Reentrancy-Eigenschaften.\n</li></ul>\n</li><li><strong><code>VariableDataPrototype</code></strong>\n<ul class=\"fig-list\"><li><em>Vererbung / Stereotypen:</em> <code>AutosarDataPrototype</code>.\n</li><li><em>Rolle:</em> Repräsentiert typisierte Datenprototypen für datenbasierte Schnittstellen sowie für per-Instance-Memory.\n</li></ul>\n</li><li><strong><code>BswInternalBehavior</code></strong>\n<ul class=\"fig-list\"><li><em>Vererbung / Stereotypen:</em> <code>InternalBehavior</code>.\n</li><li><em>Rolle:</em> Kapselung von BSW-Schedulable-Entities, Exclusive Areas, BSW-Events, Task-Mappings und instanzspezifischem Speicher.\n</li></ul>\n</li><li><strong><code>SwComponentDocumentation</code></strong>\n<ul class=\"fig-list\"><li><em>Rolle:</em> Strukturierte technische Dokumentation des Moduls.\n</li></ul>\n</li></ul>\n<h5 class=\"fig-section-h5\">Beziehungen, Kardinalitäten und Stereotypen</h5>\n<div class=\"table-wrap\"><table class=\"fig-table\"><thead><tr><th>Quell-Element</th><th>Relation / Rolle</th><th>Ziel-Element</th><th>Kardinalität</th><th>Stereotypen</th><th>Semantik</th></tr></thead><tbody><tr><td><code>BswModuleDescription</code></td><td>Komposition <code>+bswModuleDocumentation</code></td><td><code>SwComponentDocumentation</code></td><td><code>0..1</code></td><td><code>«atpVariation, atpSplitable»</code></td><td>Dokumentationsanhang; varianten- und dateisplitfähig</td></tr><tr><td><code>BswModuleDescription</code></td><td>Assoziation <code>+implementedEntry</code></td><td><code>BswModuleEntry</code></td><td><code>0..*</code></td><td><code>«atpVariation, atpSplitable»</code></td><td>Vom Modul implementierte C-APIs; varianten- und dateisplitfähig</td></tr><tr><td><code>BswModuleDescription</code></td><td>Assoziation <code>+expectedEntry</code></td><td><code>BswModuleEntry</code></td><td><code>0..*</code></td><td><code>«atpVariation, atpSplitable»</code></td><td>Vom Modul erwartete C-APIs bzw. Callbacks; varianten- und dateisplitfähig</td></tr><tr><td><code>BswModuleDescription</code></td><td>Komposition <code>+bswModuleDependency</code></td><td><code>BswModuleDependency</code></td><td><code>0..*</code></td><td><code>«atpVariation, atpSplitable»</code></td><td>Deklarierte Abhängigkeit zu anderen BSW-Modulen</td></tr><tr><td><code>BswModuleDependency</code></td><td>Assoziation <code>+targetModuleRef</code></td><td><code>BswModuleDescription</code></td><td><code>0..1</code></td><td><code>«atpUriDef, atpVariation, atpSplitable»</code></td><td>Formale Referenz auf die Beschreibung des Zielmoduls via URI; varianten- und dateisplitfähig</td></tr><tr><td><code>BswModuleDescription</code></td><td>Komposition <code>+providedModeGroup</code></td><td><code>ModeDeclarationGroupPrototype</code></td><td><code>0..* {subsets atpFeature}</code></td><td><code>«atpVariation, atpSplitable»</code></td><td>Vom Modul verwaltete / bereitgestellte Zustandsmodi; varianten- und dateisplitfähig</td></tr><tr><td><code>BswModuleDescription</code></td><td>Komposition <code>+requiredModeGroup</code></td><td><code>ModeDeclarationGroupPrototype</code></td><td><code>0..* {subsets atpFeature}</code></td><td><code>«atpVariation, atpSplitable»</code></td><td>Vom Modul überwachte / benötigte Zustandsmodi; varianten- und dateisplitfähig</td></tr><tr><td><code>BswModuleDescription</code></td><td>Komposition <code>+releasedTrigger</code></td><td><code>Trigger</code></td><td><code>0..*</code></td><td><code>«atpVariation, atpSplitable»</code></td><td>Geworfene Trigger für RTE/BswM; varianten- und dateisplitfähig</td></tr><tr><td><code>BswModuleDescription</code></td><td>Komposition <code>+requiredTrigger</code></td><td><code>Trigger</code></td><td><code>0..*</code></td><td><code>«atpVariation, atpSplitable»</code></td><td>Konsumierte Trigger zur Aktivierung von Entities; varianten- und dateisplitfähig</td></tr><tr><td><code>BswModuleDescription</code></td><td>Assoziation <code>+providedClientServerEntry</code></td><td><code>BswModuleClientServerEntry</code></td><td><code>0..*</code></td><td><code>«atpVariation, atpSplitable»</code></td><td>Vom Modul angebotene Client-Server-Operationen; varianten- und dateisplitfähig</td></tr><tr><td><code>BswModuleDescription</code></td><td>Assoziation <code>+requiredClientServerEntry</code></td><td><code>BswModuleClientServerEntry</code></td><td><code>0..*</code></td><td><code>«atpVariation, atpSplitable»</code></td><td>Vom Modul angeforderte Client-Server-Operationen; varianten- und dateisplitfähig</td></tr><tr><td><code>BswModuleDescription</code></td><td>Assoziation <code>+providedData</code></td><td><code>VariableDataPrototype</code></td><td><code>0..*</code></td><td><code>«atpVariation, atpSplitable»</code></td><td>Vom Modul bereitgestellte Datenprototypen; varianten- und dateisplitfähig</td></tr><tr><td><code>BswModuleDescription</code></td><td>Assoziation <code>+requiredData</code></td><td><code>VariableDataPrototype</code></td><td><code>0..*</code></td><td><code>«atpVariation, atpSplitable»</code></td><td>Vom Modul benötigte Datenprototypen; varianten- und dateisplitfähig</td></tr><tr><td><code>BswModuleDescription</code></td><td>Komposition <code>+internalBehavior</code></td><td><code>BswInternalBehavior</code></td><td><code>0..*</code></td><td><code>«atpSplitable»</code></td><td>Internes Ausführungsverhalten (Split erlaubt Trennung über ARXML-Dateien)</td></tr><tr><td><code>BswInternalBehavior</code></td><td>Komposition <code>+arTypedPerInstanceMemory</code></td><td><code>VariableDataPrototype</code></td><td><code>0..*</code></td><td><code>«atpVariation, atpSplitable»</code></td><td>Instanzspezifischer Speicher für das interne Verhalten; varianten- und dateisplitfähig</td></tr></tbody></table></div>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Obgleich ein statisches Metamodell vorliegt, erzwingt die Struktur folgende dynamische Interaktionsmuster zur Laufzeit:</p>\n<ul class=\"fig-list\"><li><strong>Funktionsaufrufe und Schnittstellenimplementierung:</strong>\n<ul class=\"fig-list\"><li><code>implementedEntry</code> definiert die vom BSW-Modul konkret bereitgestellten C-Funktionseinstiegspunkte (APIs, Main-Functions).\n</li><li><code>expectedEntry</code> deklariert die vom Modul für den Betrieb vorausgesetzten externen C-Funktionen bzw. Callback-Signaturen.\n</li></ul>\n</li><li><strong>Client-Server-Interaktion:</strong>\n<ul class=\"fig-list\"><li><code>providedClientServerEntry</code> und <code>requiredClientServerEntry</code> steuern Client-Server-Aufrufe, parametriert über <code>isSynchronous</code> (blockierendes vs. asynchrones Verhalten) und <code>isReentrant</code> (Wiedereintrittsfähigkeit).\n</li></ul>\n</li><li><strong>Datenbasierte Kommunikation und interner Speicher:</strong>\n<ul class=\"fig-list\"><li><code>providedData</code> und <code>requiredData</code> definieren den Datenaustausch mit anderen BSW-Modulen oder Software-Components via <code>VariableDataPrototype</code>.\n</li><li><code>arTypedPerInstanceMemory</code> stellt typisierten Speicher pro Modulinstanz bereit, auf den die Entities des <code>BswInternalBehavior</code> zur Laufzeit zugreifen.\n</li></ul>\n</li><li><strong>Modulabhängigkeiten:</strong>\n<ul class=\"fig-list\"><li><code>BswModuleDependency</code> verknüpft das Modul über <code>targetModuleId</code> bzw. über eine URI-Referenz (<code>targetModuleRef</code>) mit der abhängigen <code>BswModuleDescription</code>.\n</li></ul>\n</li><li><strong>Mode-Switching &amp; State-Propagation:</strong>\n<ul class=\"fig-list\"><li>Moduswechsel werden über <code>providedModeGroup</code> an den BSW Mode Manager (<code>BswM</code>) propagiert oder über <code>requiredModeGroup</code> konsumiert.\n</li></ul>\n</li><li><strong>Asynchrones Triggering:</strong>\n<ul class=\"fig-list\"><li>Ereignisse werden über <code>releasedTrigger</code> abgesetzt und lösen über <code>requiredTrigger</code> verknüpfte Abarbeitungsfolgen im SchM/OS aus.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>BSWMD-Erstellung (Treiber- &amp; Stack-Lieferanten):</strong>\n<ul class=\"fig-list\"><li>Jedes BSW-Modul liefert eine formale ARXML-Beschreibung mit <code>BswModuleDescription</code> als Wurzelelement.\n</li><li>C-Funktionen werden über <code>implementedEntry</code> (Export) und <code>expectedEntry</code> (Import) modelliert, wodurch die Funktionsschnittstellen für den SchM- und RTE-Generator eindeutig deklariert werden.\n</li><li>Das Attribut <code>moduleId</code> ist optional (<code>[0..1]</code>), um standardisierte sowie herstellerspezifische Module und Bibliotheken abbilden zu können.\n</li></ul>\n</li><li><strong>Packaging, Variantenbildung und Splitfähigkeit:</strong>\n<ul class=\"fig-list\"><li>Sämtliche Schnittstellenrollen an <code>BswModuleDescription</code>, <code>arTypedPerInstanceMemory</code> an <code>BswInternalBehavior</code> sowie <code>targetModuleRef</code> an <code>BswModuleDependency</code> besitzen den Stereotyp <code>«atpSplitable»</code>. Dies erlaubt eine vollständige dateiübergreifende Aufteilung auch von externen Modulverweisen (<code>«atpUriDef, atpVariation, atpSplitable»</code>).\n</li><li><code>«atpVariation»</code> ermöglicht durchgängige Variantenbildung über System-Constants.\n</li></ul>\n</li><li><strong>Generierung des Basic Software Schedulers (SchM):</strong>\n<ul class=\"fig-list\"><li>Die Verknüpfung von <code>BswModuleDescription</code> mit <code>BswInternalBehavior</code> steuert die Generierung der <code>SchM_&lt;Bsw&gt;.h</code>-Header (z. B. Exclusive Areas via <code>SchM_Enter_&lt;Mod&gt;_&lt;Area&gt;()</code> und zyklische Main-Functions via <code>SchM_ActMainFunction_&lt;Mod&gt;()</code>).\n</li></ul>\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-f5ce8c3b9c723c57", "to": "FIG-0426f7d89d8bb8d2", "fr": "R4.0.3", "tr": "R4.1.3", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li><code>BswModuleDescription</code>: Attribut <code>moduleId</code> von obligatorisch <code>PositiveInteger</code> auf optional <code>PositiveInteger [0..1]</code> geändert.\n</li><li><code>BswModuleDependency</code>: Attribut <code>targetModuleId</code> von obligatorisch <code>PositiveInteger</code> auf optional <code>PositiveInteger [0..1]</code> geändert.\n</li><li><code>BswModuleDependency</code>: Assoziation <code>+targetModuleRef</code> zu <code>BswModuleDescription</code> mit Multiplizität <code>0..1</code> und Stereotyp <code>«atpUriDef,atpVariation»</code> ergänzt.\n</li><li><code>BswModuleDependency</code>: Assoziationen <code>+requiredEntry</code> (<code>0..*</code>) und <code>+expectedCallback</code> (<code>0..*</code>) zu <code>BswModuleEntry</code> entfernt.\n</li><li><code>BswModuleClientServerEntry</code>: Klasse mit Stereotyp <code>Referrable</code> und Attributen <code>+ isReentrant :Boolean [0..1]</code> sowie <code>+ isSynchronous :Boolean [0..1]</code> neu eingeführt.\n</li><li><code>BswModuleDescription</code>: Assoziationen <code>+providedClientServerEntry</code> (<code>0..*</code>, <code>«atpVariation»</code>) und <code>+requiredClientServerEntry</code> (<code>0..*</code>, <code>«atpVariation»</code>) zu <code>BswModuleClientServerEntry</code> ergänzt.\n</li><li><code>VariableDataPrototype</code>: Klasse mit Stereotyp <code>AutosarDataPrototype</code> neu eingeführt.\n</li><li><code>BswModuleDescription</code>: Assoziationen <code>+providedData</code> (<code>0..*</code>, <code>«atpVariation»</code>) und <code>+requiredData</code> (<code>0..*</code>, <code>«atpVariation»</code>) zu <code>VariableDataPrototype</code> ergänzt.\n</li><li><code>ModeDeclarationGroup</code>: Klasse (Stereotypen <code>ARElement</code>, <code>AtpBlueprint</code>, <code>AtpBlueprintable</code>, <code>AtpType</code>, Attribut <code>onTransitionValue</code>) und Assoziation <code>«isOfType» +type: ModeDeclarationGroup [1]</code> von <code>ModeDeclarationGroupPrototype</code> aus dem Diagramm entfernt.\n</li></ul>"}, {"from": "FIG-0426f7d89d8bb8d2", "to": "FIG-4e7618412e0e28e1", "fr": "R4.1.3", "tr": "R4.2.2", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li><code>BswModuleDescription</code>: Stereotyp von <code>«atpVariation»</code> auf <code>«atpVariation,atpSplitable»</code> an folgenden Assoziationen erweitert:\n<ul class=\"fig-list\"><li><code>+providedEntry</code> (zu <code>BswModuleEntry</code>)\n</li><li><code>+outgoingCallback</code> (zu <code>BswModuleEntry</code>)\n</li><li><code>+providedModeGroup</code> (zu <code>ModeDeclarationGroupPrototype</code>)\n</li><li><code>+requiredModeGroup</code> (zu <code>ModeDeclarationGroupPrototype</code>)\n</li><li><code>+releasedTrigger</code> (zu <code>Trigger</code>)\n</li><li><code>+requiredTrigger</code> (zu <code>Trigger</code>)\n</li><li><code>+providedClientServerEntry</code> (zu <code>BswModuleClientServerEntry</code>)\n</li><li><code>+requiredClientServerEntry</code> (zu <code>BswModuleClientServerEntry</code>)\n</li><li><code>+providedData</code> (zu <code>VariableDataPrototype</code>)\n</li><li><code>+requiredData</code> (zu <code>VariableDataPrototype</code>)\n</li></ul>\n</li></ul>"}, {"from": "FIG-4e7618412e0e28e1", "to": "FIG-2a2380d146215670", "fr": "R4.2.2", "tr": "R4.3.1", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li><code>BswModuleDescription</code>: Assoziation <code>+providedEntry</code> umbenannt/ersetzt durch <code>+implementedEntry</code> (<code>0..*</code>, <code>«atpVariation,atpSplitable»</code>) zu <code>BswModuleEntry</code>.\n</li><li><code>BswModuleDescription</code>: Assoziation <code>+outgoingCallback</code> umbenannt/ersetzt durch <code>+expectedEntry</code> (<code>0..*</code>, <code>«atpVariation,atpSplitable»</code>) zu <code>BswModuleEntry</code>.\n</li><li><code>BswInternalBehavior</code>: Neue Kompositions-Beziehung <code>+arTypedPerInstanceMemory</code> (<code>0..*</code>, <code>«atpVariation,atpSplitable»</code>) zu <code>VariableDataPrototype</code> ergänzt.\n</li></ul>"}, {"from": "FIG-2a2380d146215670", "to": "FIG-80fe9df33049322e", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li><code>BswModuleDescription</code>, <code>BswModuleDependency</code>, <code>ModeDeclarationGroupPrototype</code>, <code>Trigger</code>, <code>BswModuleClientServerEntry</code>: Leerzeichen vor dem Doppelpunkt bei Typdeklarationen der Attribute entfernt (z. B. <code>+ moduleId :PositiveInteger [0..1]</code> zu <code>+ moduleId: PositiveInteger [0..1]</code>).\n</li><li>Diagrammlayout neu gerendert ohne inhaltliche Modelländerungen.\n</li></ul>"}, {"from": "FIG-80fe9df33049322e", "to": "FIG-7c1709db862b310e", "fr": "R21-11", "tr": "R22-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li><code>BswModuleDependency</code>: Assoziation <code>+targetModuleRef</code> zu <code>BswModuleDescription</code> erweitert Stereotyp von <code>«atpUriDef,atpVariation»</code> auf <code>«atpUriDef,atpVariation,atpSplitable»</code> (Splitfähigkeit ergänzt).\n</li></ul>"}, {"from": "FIG-7c1709db862b310e", "to": "FIG-cb916ca9f81890ee", "fr": "R22-11", "tr": "R23-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-cb916ca9f81890ee", "to": "FIG-7c346486e3c18ffb", "fr": "R23-11", "tr": "R24-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li><code>BswModuleDescription</code>: An den Kompositionen <code>+providedModeGroup</code> und <code>+requiredModeGroup</code> zu <code>ModeDeclarationGroupPrototype</code> wurde die Eigenschaftsbeschränkung <code>{subsets atpFeature}</code> ergänzt.\n</li><li><code>SwComponentDocumentation</code>: Die Kennzeichnung in der rechten unteren Klassenecke („A“) wurde durch ein Dokumentensymbol ersetzt.\n</li></ul>"}, {"from": "FIG-7c346486e3c18ffb", "to": "FIG-8259e072517b0262", "fr": "R24-11", "tr": "R25-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li><code>BswModuleDescription</code>: Die Beschriftungen <code>0..* {subsets atpFeature}</code> an den Assoziationsenden <code>providedModeGroup</code> und <code>requiredModeGroup</code> wurden im Layout entzerrt, sodass sie nicht mehr mit den Stereotypen und Rollennamen überlappen.\n</li></ul>"}]};
